        .tier-天灾 { background: var(--tier-catastrophe); }

        .rank-无 { background: var(--rank-none); }
        .rank-F { background: var(--rank-f); }
        .rank-E { background: var(--rank-e); }
        .rank-D { background: var(--rank-d); }
        .rank-C { background: var(--rank-c); }
        .rank-B { background: var(--rank-b); }
        .rank-A { background: var(--rank-a); }
        .rank-S { background: var(--rank-s); }

        .appearance-card .description-text {
            font-size: 13px;
            line-height: 1.8;
            margin-bottom: 10px;
            color: var(--text-light);
