        .attribute-value {
            font-size: 48px;
            font-weight: bold;
            color: var(--text-gold);
            text-shadow: 3px 3px 6px rgba(0, 0, 0, 0.5);
            margin: 20px 0;
        }

        .attribute-eval {
            font-size: 13px;
            color: var(--text-light);
            font-style: italic;
            line-height: 1.5;
        }

        .abilities-list {
            display: flex;
            flex-direction: column;
            gap: 15px;
        }

        .ability-item {
            background: rgba(184, 134, 11, 0.1);
            border-left: 4px solid var(--brass-main);
            padding: 15px;
            border-radius: 5px;
        }

        .ability-name {
            font-size: 16px;
            font-weight: bold;
            color: var(--text-gold);
            margin-bottom: 8px;
        }

        .ability-desc {
            font-size: 13px;
            color: var(--text-light);
            margin-bottom: 5px;
        }

        .ability-eval {
            font-size: 12px;
            color: var(--brass-lighter);
            font-style: italic;
        }

        .items-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
            gap: 15px;
        }

        .item-card {
            background: rgba(205, 133, 63, 0.15);
            border: 1px solid var(--brass-main);
            padding: 15px;
            border-radius: 8px;
        }

        .item-name {
            font-size: 15px;
            font-weight: bold;
            color: var(--text-gold);
            margin-bottom: 8px;
        }

        .item-info {
            font-size: 13px;
            color: var(--text-light);
            white-space: pre-wrap;
        }

        .teammates-list {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 20px;
        }

        .teammate-card {
            background: linear-gradient(135deg, rgba(184, 134, 11, 0.15) 0%, rgba(62, 39, 35, 0.5) 100%);
            border: 2px solid var(--brass-main);
            border-radius: 10px;
            padding: 20px;
        }

        .teammate-header {
            font-size: 18px;
            font-weight: bold;
            color: var(--text-gold);
            margin-bottom: 12px;
            text-align: center;
        }

        .teammate-info {
            display: flex;
            flex-direction: column;
            gap: 8px;
            margin-bottom: 12px;
        }

        .teammate-row {
            display: flex;
            justify-content: space-between;
            font-size: 13px;
        }

        .teammate-label {
            color: var(--brass-lighter);
            font-weight: bold;
        }

        .teammate-value {
            color: var(--text-light);
        }

        .teammate-eval {
            font-size: 13px;
            color: var(--text-light);
            font-style: italic;
            padding: 10px;
            background: rgba(0, 0, 0, 0.2);
            border-radius: 5px;
            margin-bottom: 10px;
        }

        .affection-bar {
            width: 100%;
            height: 20px;
            background: rgba(0, 0, 0, 0.3);
            border-radius: 10px;
            overflow: hidden;
            position: relative;
        }

        .affection-fill {
            height: 100%;
            background: linear-gradient(to right, #E74C3C, #F39C12, #52B788);
            transition: width 0.3s;
            display: flex;
            align-items: center;
            justify-content: center;
            font-size: 11px;
            font-weight: bold;
            color: white;
            text-shadow: 1px 1px 2px rgba(0, 0, 0, 0.7);
        }

        .empty-state {
            text-align: center;
