<body>
    <div id="status-container">
        <div class="top-bar">
            <div class="world-status" id="worldStatus">加载中...</div>
            <div class="currency-display" id="currencyDisplay"></div>
        </div>

        <div class="todo-section">
            <h3>待办事项</h3>
            <ul class="todo-list" id="todoList"></ul>
        </div>

        <input type="radio" name="tab" id="tab1" class="tab-nav-input" checked>
        <input type="radio" name="tab" id="tab2" class="tab-nav-input">
        <input type="radio" name="tab" id="tab3" class="tab-nav-input">
        <input type="radio" name="tab" id="tab4" class="tab-nav-input">
        <input type="radio" name="tab" id="tab5" class="tab-nav-input">

        <div class="tab-navigation">
            <label for="tab1">基础信息</label>
            <label for="tab2">属性</label>
            <label for="tab3">能力</label>
            <label for="tab4">随身物品</label>
            <label for="tab5">队友</label>
        </div>

        <div class="tab-content-wrapper">
            <div id="content1" class="tab-content">
                <div class="info-grid">
                    <div class="info-card">
                        <h2 id="playerName">加载中...</h2>
                        <div id="basicInfo"></div>
                        <div id="tierRank"></div>
                    </div>
                    <div class="info-card appearance-card">
                        <h2>外貌身材</h2>
                        <div id="appearanceInfo"></div>
                        <div class="overall-description" id="overallDesc"></div>
                        <h3 style="margin-top: 20px; color: var(--brass-lighter); font-size: 14px;">目前状态</h3>
                        <div class="status-tags" id="statusTags"></div>
                    </div>
                </div>
            </div>

            <div id="content2" class="tab-content">
                <div class="attributes-grid" id="attributesGrid"></div>
            </div>

            <div id="content3" class="tab-content">
                <div class="abilities-list" id="abilitiesList"></div>
            </div>

            <div id="content4" class="tab-content">
                <div class="items-grid" id="itemsGrid"></div>
            </div>

            <div id="content5" class="tab-content">
                <div class="teammates-list" id="teammatesList"></div>
            </div>
        </div>
    </div>

    <script>
        async function updateStatus() {
            try {
                // ========== 世界状态（逐个获取）==========
                const era = await STscript('/xbgetvar 世界.世界状态.日期.当前纪元');
                const calendar = await STscript('/xbgetvar 世界.世界状态.日期.使用历法');
                const year = await STscript('/xbgetvar 世界.世界状态.日期.年份');
                const month = await STscript('/xbgetvar 世界.世界状态.日期.月份');
                const day = await STscript('/xbgetvar 世界.世界状态.日期.日期');
                const weekday = await STscript('/xbgetvar 世界.世界状态.日期.星期');
                const time = await STscript('/xbgetvar 世界.世界状态.时间');

                document.getElementById('worldStatus').innerHTML =
                    `${era}，${calendar}：${year}年，${month}月${day}日，${weekday}，${time}`;

                // ========== 钱财（逐个获取）==========
                const crystal = await STscript('/xbgetvar 世界.玩家状态.钱财.魔晶币');
                const gold = await STscript('/xbgetvar 世界.玩家状态.钱财.金币');
                const silver = await STscript('/xbgetvar 世界.玩家状态.钱财.银币');
                const copper = await STscript('/xbgetvar 世界.玩家状态.钱财.铜币');

                document.getElementById('currencyDisplay').innerHTML = `
                    <div class="currency-item">
                        <svg fill="#C0C0FF" viewBox="0 0 24 24"><path d="M12 2L2 7l10 5 10-5-10-5zM2 17l10 5 10-5M2 12l10 5 10-5"/></svg>
                        <span>${crystal || 0}</span>
                    </div>
                    <div class="currency-item">
                        <svg fill="#FFD700" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg>
                        <span>${gold || 0}</span>
                    </div>
                    <div class="currency-item">
                        <svg fill="#C0C0C0" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg>
                        <span>${silver || 0}</span>
                    </div>
                    <div class="currency-item">
                        <svg fill="#CD853F" viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/></svg>
                        <span>${copper || 0}</span>
                    </div>
                `;

                // ========== 待办事项（一次性获取，STscript已返回对象）==========
                const todoData = await STscript('/xbgetvar 世界.玩家状态.待办事项');
                console.log('待办事项原始数据:', todoData);
                let todoHTML = '';
                if (todoData && Array.isArray(todoData) && todoData.length > 0) {
                    todoData.forEach(item => {
                        todoHTML += `<li class="todo-item">• ${item}</li>`;
                    });
                } else {
                    todoHTML = '<li class="todo-item" style="color: var(--brass-lighter); font-style: italic;">暂无待办事项</li>';
                }
                document.getElementById('todoList').innerHTML = todoHTML;

                // ========== 基础信息（逐个字段获取）==========
                const playerName = await STscript('/xbgetvar 世界.玩家状态.基础信息.名字');
                const playerAge = await STscript('/xbgetvar 世界.玩家状态.基础信息.年龄');
                const playerGender = await STscript('/xbgetvar 世界.玩家状态.基础信息.性别');
                const playerRace = await STscript('/xbgetvar 世界.玩家状态.基础信息.种族');
                const playerJob = await STscript('/xbgetvar 世界.玩家状态.基础信息.职业');
                const playerFaith = await STscript('/xbgetvar 世界.玩家状态.基础信息.信仰');

                console.log('基础信息:', {playerName, playerAge, playerGender, playerRace, playerJob, playerFaith});

                document.getElementById('playerName').textContent = playerName || '未命名冒险者';

                let basicHTML = '';
                if (playerAge) {
                    basicHTML += `<div class="info-row"><span class="info-label">年龄:</span><span class="info-value">${playerAge}</span></div>`;
                }
                if (playerGender) {
                    basicHTML += `<div class="info-row"><span class="info-label">性别:</span><span class="info-value">${playerGender}</span></div>`;
                }
                if (playerRace) {
                    basicHTML += `<div class="info-row"><span class="info-label">种族:</span><span class="info-value">${playerRace}</span></div>`;
                }
                if (playerJob) {
                    basicHTML += `<div class="info-row"><span class="info-label">职业:</span><span class="info-value">${playerJob}</span></div>`;
                }
                if (playerFaith) {
                    basicHTML += `<div class="info-row"><span class="info-label">信仰:</span><span class="info-value">${playerFaith}</span></div>`;
                }
                document.getElementById('basicInfo').innerHTML = basicHTML;

                // ========== 力量阶位 & 冒险者等级（逐个获取）==========
                const tier = await STscript('/xbgetvar 世界.玩家状态.力量阶位');
                const rank = await STscript('/xbgetvar 世界.玩家状态.冒险者等级');

                console.log('力量阶位与等级:', {tier, rank});

                document.getElementById('tierRank').innerHTML = `
                    <div class="info-row">
                        <span class="info-label">力量阶位:</span>
                        <span class="tier-badge tier-${tier || '学徒'}">${tier || '未知'}</span>
                    </div>
                    <div class="info-row">
                        <span class="info-label">冒险者等级:</span>
                        <span class="rank-badge rank-${rank || '无'}">${rank || '无'}</span>
                    </div>
                `;

                // ========== 外貌身材（逐个获取）==========
                const appearanceDesc = await STscript('/xbgetvar 世界.玩家状态.外貌身材.外貌描述');
                const bodyDesc = await STscript('/xbgetvar 世界.玩家状态.外貌身材.身材描述');
                const overallDesc = await STscript('/xbgetvar 世界.玩家状态.外貌身材.整体描述');

                document.getElementById('appearanceInfo').innerHTML = `
                    <div class="description-text"><strong>外貌：</strong>${appearanceDesc || '暂无描述'}</div>
                    <div class="description-text"><strong>身材：</strong>${bodyDesc || '暂无描述'}</div>
                `;
                document.getElementById('overallDesc').textContent = overallDesc || '暂无整体描述';

                // ========== 目前状态（一次性获取对象，直接使用）==========
                const statusObj = await STscript('/xbgetvar 世界.玩家状态.目前状态');
                console.log('目前状态数据:', statusObj);
                let statusHTML = '';
                if (statusObj && typeof statusObj === 'object' && Object.keys(statusObj).length > 0) {
                    for (const [name, data] of Object.entries(statusObj)) {
                        const desc = data?.描述 || '';
                        const eval_ = data?.评价 || '';
                        statusHTML += `<span class="status-tag" data-desc="${desc}" data-eval="${eval_}">${name}</span>`;
                    }
                } else {
                    statusHTML = '<div class="empty-state">暂无状态</div>';
                }
                document.getElementById('statusTags').innerHTML = statusHTML;

                // ========== 属性（逐个获取）==========
                const attrs = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
                let attrHTML = '';
                for (const attr of attrs) {
                    const val = await STscript(`/xbgetvar 世界.玩家状态.属性.${attr}`);
                    const eval_ = await STscript(`/xbgetvar 世界.玩家状态.属性.${attr}自我评价`);
                    attrHTML += `
                        <div class="attribute-card">
                            <div class="attribute-name">${attr}</div>
                            <div class="attribute-value">${val || 0}</div>
                            <div class="attribute-eval">${eval_ || '暂无评价'}</div>
                        </div>
                    `;
                }
                document.getElementById('attributesGrid').innerHTML = attrHTML;

                // ========== 能力（一次性获取对象，直接使用）==========
                const abilitiesObj = await STscript('/xbgetvar 世界.玩家状态.能力');
                console.log('能力数据:', abilitiesObj);
                let abilitiesHTML = '';
                if (abilitiesObj && typeof abilitiesObj === 'object' && Object.keys(abilitiesObj).length > 0) {
                    for (const [name, data] of Object.entries(abilitiesObj)) {
                        const desc = data?.描述 || '暂无描述';
                        const eval_ = data?.评价 || '暂无评价';
                        abilitiesHTML += `
                            <div class="ability-item">
                                <div class="ability-name">${name}</div>
                                <div class="ability-desc">${desc}</div>
                                <div class="ability-eval">评价: ${eval_}</div>
                            </div>
                        `;
                    }
                } else {
                    abilitiesHTML = '<div class="empty-state">暂无能力</div>';
                }
                document.getElementById('abilitiesList').innerHTML = abilitiesHTML;

                // ========== 随身物品（一次性获取对象，直接使用）==========
                const itemsObj = await STscript('/xbgetvar 世界.玩家状态.随身物品');
                console.log('随身物品数据:', itemsObj);
                let itemsHTML = '';
                if (itemsObj && typeof itemsObj === 'object' && Object.keys(itemsObj).length > 0) {
                    for (const [name, info] of Object.entries(itemsObj)) {
                        const infoText = typeof info === 'object' ? JSON.stringify(info, null, 2) : info;
                        itemsHTML += `
                            <div class="item-card">
                                <div class="item-name">${name}</div>
                                <div class="item-info">${infoText || '暂无信息'}</div>
                            </div>
                        `;
                    }
                } else {
                    itemsHTML = '<div class="empty-state">暂无物品</div>';
                }
                document.getElementById('itemsGrid').innerHTML = itemsHTML;

                // ========== 队友（一次性获取对象，直接使用）==========
                const teammatesObj = await STscript('/xbgetvar 世界.队友');
                console.log('队友数据:', teammatesObj);
                let teammatesHTML = '';
                if (teammatesObj && typeof teammatesObj === 'object' && Object.keys(teammatesObj).length > 0) {
                    for (const [name, data] of Object.entries(teammatesObj)) {
                        const gender = data?.性别 || '未知';
                        const race = data?.种族 || '未知';
                        const eval_ = data?.评价 || '暂无评价';
                        const affection = data?.好感度 || 0;
                        const affectionPercent = ((affection + 100) / 200) * 100;
                        teammatesHTML += `
                            <div class="teammate-card">
                                <div class="teammate-header">${name}</div>
                                <div class="teammate-info">
                                    <div class="teammate-row">
                                        <span class="teammate-label">性别:</span>
                                        <span class="teammate-value">${gender}</span>
                                    </div>
                                    <div class="teammate-row">
                                        <span class="teammate-label">种族:</span>
                                        <span class="teammate-value">${race}</span>
                                    </div>
                                </div>
                                <div class="teammate-eval">${eval_}</div>
                                <div class="affection-bar">
                                    <div class="affection-fill" style="width: ${affectionPercent}%">${affection}</div>
                                </div>
                            </div>
                        `;
                    }
                } else {
                    teammatesHTML = '<div class="empty-state">暂无队友</div>';
                }
                document.getElementById('teammatesList').innerHTML = teammatesHTML;

            } catch (error) {
                console.error('更新状态时出错:', error);
            }
        }

        let isUpdating = false;
        async function runUpdate() {
            if (isUpdating) return;
            isUpdating = true;
            try {
                await updateStatus();
            } catch (error) {
                console.error('运行更新时出错:', error);
            } finally {
                isUpdating = false;
            }
        }

        runUpdate();
        setInterval(runUpdate, 5000);
    </script>
</body>
</html>
