    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>转生协议身份构筑</title>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Orbitron:wght@400;700&family=Noto+Sans+SC:wght@300;400;700&display=swap" rel="stylesheet">

    <style>
        :root {
            --bg-dark-void: #0a0a1f;
            --bg-panel: rgba(15, 10, 35, 0.92);
            --text-primary: #e8e8f0;
            --text-secondary: #9090c8;
            --accent-purple: #7a2fff;
            --accent-cyan: #00f2ff;
            --border-glow: rgba(0, 242, 255, 0.85);
            --interactive-highlight: #b366ff;
            --disabled-color: #4a4a6a;
            --font-tech: 'Orbitron', 'Noto Sans SC', sans-serif;
            --font-body: 'Noto Sans SC', sans-serif;
        }

        *, *::before, *::after { box-sizing: border-box; }
        html { font-size: 16px; }
        @media (max-width: 768px) { html { font-size: 14px; } }

        html, body { height: 100%; margin: 0; }

        body {
            font-family: var(--font-body);
            color: var(--text-primary);
            background-color: var(--bg-dark-void);
            background-image:
                repeating-linear-gradient(0deg, transparent, transparent 2px, rgba(0, 242, 255, 0.03) 2px, rgba(0, 242, 255, 0.03) 4px),
                radial-gradient(circle at 1px 1px, rgba(122, 47, 255, 0.15) 1px, transparent 0);
            background-size: 100% 4px, 30px 30px;
            animation: scanline 8s linear infinite;
            padding: 1rem;
            min-height: 100vh;
            overflow-y: auto;
        }

        @keyframes scanline {
            0% { background-position: 0 0, 0 0; }
            100% { background-position: 0 100vh, 0 0; }
        }

        .holographic-panel {
            width: 100%;
            max-width: 600px;
            margin: 0 auto;
            padding: 2rem;
            background: var(--bg-panel);
            border: 2px solid var(--accent-cyan);
            box-shadow:
                0 0 20px var(--border-glow),
                inset 0 0 15px rgba(122, 47, 255, 0.2),
                0 0 40px rgba(0, 242, 255, 0.3);
            border-radius: 12px;
            backdrop-filter: blur(8px);
            position: relative;
        }

        .holographic-panel::before {
            content: '';
            position: absolute;
            top: -2px; left: -2px; right: -2px; bottom: -2px;
            background: linear-gradient(45deg, var(--accent-purple), var(--accent-cyan), var(--accent-purple));
            background-size: 300% 300%;
            border-radius: 12px;
            z-index: -1;
            opacity: 0.3;
            animation: gradient-shift 6s ease infinite;
        }

        @keyframes gradient-shift {
            0%, 100% { background-position: 0% 50%; }
            50% { background-position: 100% 50%; }
        }

        @media (max-width: 768px) {
            .holographic-panel { padding: 1.5rem; max-width: 100%; }
        }

        #difficulty-selector { text-align: center; }
        #difficulty-selector h2 {
            font-family: var(--font-tech);
            font-size: 2.2rem;
            margin: 0 0 0.5rem 0;
            color: var(--accent-cyan);
            text-shadow: 0 0 10px var(--accent-cyan), 0 0 20px rgba(0, 242, 255, 0.5);
            letter-spacing: 2px;
        }
        #difficulty-selector p {
            margin-bottom: 2rem;
            font-size: 1rem;
            color: var(--text-secondary);
        }
        .difficulty-options { display: flex; flex-direction: column; gap: 1.2rem; }

        .genesis-folio {
            max-width: 1000px;
            display: none;
            flex-direction: column;
            min-height: 100vh;
        }

        @media (max-width: 768px) {
            .genesis-folio { min-height: auto; }
        }

        .folio-header h1 {
            font-family: var(--font-tech);
            font-size: 2.8rem;
            text-align: center;
            margin: 0 0 1.5rem 0;
            padding-bottom: 1.2rem;
            border-bottom: 2px solid var(--accent-cyan);
            color: var(--accent-cyan);
            text-shadow: 0 0 12px var(--accent-cyan), 0 0 24px rgba(0, 242, 255, 0.6);
            letter-spacing: 3px;
        }

        @media (max-width: 768px) {
            .folio-header h1 { font-size: 2rem; letter-spacing: 1px; }
        }

        .folio-content { padding-bottom: 2rem; }

        .folio-section { margin-bottom: 2.5rem; }
        .folio-section h3 {
            font-family: var(--font-tech);
            font-size: 1.6rem;
            color: var(--accent-purple);
            margin-bottom: 1.2rem;
            padding-bottom: 0.6rem;
            border-bottom: 2px dashed var(--accent-purple);
            text-shadow: 0 0 8px var(--accent-purple), 0 0 16px rgba(122, 47, 255, 0.5);
            letter-spacing: 1px;
        }

        .form-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
            gap: 1.2rem;
        }

        @media (max-width: 768px) {
            .form-grid { grid-template-columns: 1fr; gap: 1rem; }
        }

        .form-group { margin-bottom: 0; }
        .form-group label {
            display: block;
            font-weight: 700;
            margin-bottom: 0.6rem;
            color: var(--text-secondary);
            font-size: 0.95rem;
        }
        .form-group small {
            color: var(--text-secondary);
            font-size: 0.85rem;
            display: block;
            margin-top: 0.3rem;
        }

        .form-input, .form-select, .form-textarea {
            width: 100%;
            padding: 0.85rem;
            font-family: var(--font-body);
            font-size: 1rem;
            background-color: rgba(0,0,0,0.4);
            border: 1px solid var(--accent-purple);
            border-radius: 6px;
            transition: all 0.3s ease;
            color: var(--text-primary);
        }
        .form-input:focus, .form-select:focus, .form-textarea:focus {
            outline: none;
            border-color: var(--accent-cyan);
            box-shadow: 0 0 12px var(--border-glow), inset 0 0 8px rgba(0, 242, 255, 0.15);
            background-color: rgba(0,0,0,0.6);
        }
        .form-textarea { resize: vertical; min-height: 100px; }

        .checkbox-group {
            display: flex;
            align-items: center;
            gap: 0.5rem;
        }
        .checkbox-group input[type="checkbox"] {
            width: 20px;
            height: 20px;
            accent-color: var(--accent-cyan);
            cursor: pointer;
        }
        .checkbox-group label {
            margin: 0;
            cursor: pointer;
        }

        .input-with-button { display: flex; align-items: flex-start; gap: 0.6rem; }
        .dice-btn {
            background: transparent;
            border: 2px solid var(--accent-cyan);
            color: var(--accent-cyan);
            min-width: 50px;
            height: 50px;
            font-size: 1.8rem;
            cursor: pointer;
            border-radius: 8px;
            transition: all 0.3s ease;
            flex-shrink: 0;
        }
        .dice-btn:hover {
            background: var(--accent-cyan);
            color: var(--bg-dark-void);
            box-shadow: 0 0 15px var(--border-glow);
            transform: scale(1.05);
        }

        @media (max-width: 768px) {
            .dice-btn { min-width: 45px; height: 45px; font-size: 1.5rem; }
        }

        .action-btn {
            display: inline-block;
            background: linear-gradient(135deg, var(--accent-purple), var(--interactive-highlight));
            color: #fff;
            padding: 1rem 1.8rem;
            border: 2px solid var(--accent-cyan);
            border-radius: 8px;
            font-family: var(--font-tech);
            font-size: 1.2rem;
            cursor: pointer;
            transition: all 0.3s ease;
            text-shadow: 0 0 5px rgba(0,0,0,0.5);
            font-weight: 700;
            box-shadow: 0 0 15px rgba(122, 47, 255, 0.5);
        }
        .action-btn:hover:not(:disabled) {
            transform: translateY(-3px);
            box-shadow: 0 6px 20px rgba(122, 47, 255, 0.7), 0 0 25px var(--border-glow);
            background: linear-gradient(135deg, var(--interactive-highlight), var(--accent-purple));
        }
        .action-btn:disabled {
            background: var(--disabled-color);
            color: #2e2e4f;
            cursor: not-allowed;
            transform: none;
            box-shadow: none;
            border-color: #4a4a6a;
        }

        @media (max-width: 768px) {
            .action-btn { padding: 0.9rem 1.5rem; font-size: 1.1rem; }
        }

        .attribute-header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            margin-bottom: 1.2rem;
            flex-wrap: wrap;
            gap: 1rem;
        }
        .points-display {
            font-family: var(--font-tech);
            font-size: 1.3rem;
            color: var(--accent-cyan);
            text-shadow: 0 0 8px var(--accent-cyan);
        }

        @media (max-width: 768px) {
            .attribute-header { flex-direction: column; align-items: flex-start; }
        }

        .power-tier-container, .adventurer-rank-container {
            text-align: right;
        }

        @media (max-width: 768px) {
            .power-tier-container, .adventurer-rank-container {
                text-align: left;
                width: 100%;
            }
        }

        .power-tier-display, .adventurer-rank-display {
            font-family: var(--font-tech);
            font-size: 1.4rem;
            padding: 0.4rem 1rem;
            border-radius: 6px;
            font-weight: bold;
            display: inline-block;
            transition: all 0.4s ease;
            box-shadow: 0 0 10px rgba(0,0,0,0.5);
        }

        @media (max-width: 768px) {
            .power-tier-display, .adventurer-rank-display { font-size: 1.2rem; }
        }

        .power-tier-学徒 { background-color: #6c757d; color: #fff; }
        .power-tier-正式 { background-color: #28a745; color: #fff; }
        .power-tier-精英 { background-color: #007bff; color: #fff; }
        .power-tier-大师 { background-color: #9f50ff; color: #fff; text-shadow: 0 0 8px #fff; }
        .power-tier-传奇 { background-color: #fd7e14; color: #fff; text-shadow: 0 0 10px #fff; }
        .power-tier-天灾 {
            background-color: #dc3545;
            color: #fff;
            text-shadow: 0 0 12px #fff;
            animation: pulse-tier 1.5s infinite;
        }

        @keyframes pulse-tier {
            0%, 100% { box-shadow: 0 0 0 0 rgba(220, 53, 69, 0.8); }
            50% { box-shadow: 0 0 0 12px rgba(220, 53, 69, 0); }
        }

        .adventurer-rank-无 { background-color: #6c757d; color: #fff; }
        .adventurer-rank-F { background-color: #8b4513; color: #fff; }
        .adventurer-rank-E { background-color: #a0522d; color: #fff; }
        .adventurer-rank-D { background-color: #28a745; color: #fff; }
        .adventurer-rank-C { background-color: #17a2b8; color: #fff; }
        .adventurer-rank-B { background-color: #007bff; color: #fff; }
        .adventurer-rank-A { background-color: #9f50ff; color: #fff; text-shadow: 0 0 8px #fff; }
        .adventurer-rank-S {
            background-color: #ffc107;
            color: #000;
            text-shadow: 0 0 10px rgba(255,193,7,0.8);
            animation: pulse-rank 1.5s infinite;
        }

        @keyframes pulse-rank {
            0%, 100% { box-shadow: 0 0 0 0 rgba(255, 193, 7, 0.8); }
            50% { box-shadow: 0 0 0 12px rgba(255, 193, 7, 0); }
        }

        .tier-comment, .rank-comment {
            margin-top: 0.6rem;
            font-size: 0.9rem;
            color: var(--text-secondary);
            font-style: italic;
            line-height: 1.4;
        }

        .attribute-grid {
            display: grid;
            grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
            gap: 1.2rem;
        }

        @media (max-width: 768px) {
            .attribute-grid { grid-template-columns: 1fr; }
        }

        .attribute-item {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 0.6rem 1.2rem;
            background: rgba(0,0,0,0.3);
            border-left: 4px solid var(--accent-purple);
            border-radius: 6px;
            box-shadow: 0 0 8px rgba(122, 47, 255, 0.3);
        }
        .attribute-item .attr-name {
            font-weight: 700;
            flex-shrink: 0;
            margin-right: 1rem;
            font-family: var(--font-tech);
        }
        .attr-controls { display: flex; align-items: center; gap: 0.6rem; }
        .attr-controls button {
            width: 36px;
            height: 36px;
            border-radius: 50%;
            border: 2px solid var(--accent-cyan);
            background: transparent;
            color: var(--accent-cyan);
            font-size: 1.6rem;
            line-height: 32px;
            cursor: pointer;
            transition: all 0.3s ease;
            box-shadow: 0 0 5px rgba(0, 242, 255, 0.3);
        }
        .attr-controls button:hover:not(:disabled) {
            background-color: var(--accent-cyan);
            color: var(--bg-dark-void);
            box-shadow: 0 0 12px var(--border-glow);
            transform: scale(1.1);
        }
        .attr-controls button:disabled {
            border-color: var(--disabled-color);
            color: var(--disabled-color);
            cursor: not-allowed;
            box-shadow: none;
        }
        .attr-controls .attr-value {
            width: 55px;
            text-align: center;
            font-size: 1.9rem;
            font-weight: 700;
            color: var(--text-primary);
            font-family: var(--font-tech);
            text-shadow: 0 0 5px rgba(255,255,255,0.3);
        }

        @media (max-width: 768px) {
            .attr-controls button { width: 32px; height: 32px; font-size: 1.4rem; }
            .attr-controls .attr-value { font-size: 1.6rem; width: 50px; }
        }

        .slider-group { margin-top: 1.8rem; }
        .slider-group label { display: block; margin-bottom: 0.6rem; font-weight: 700; }
        .slider-container { display: flex; align-items: center; gap: 1.2rem; }
        input[type="range"] {
            flex-grow: 1;
            -webkit-appearance: none;
            appearance: none;
            width: 100%;
            height: 10px;
            background: rgba(0,0,0,0.5);
            border-radius: 5px;
            outline: none;
            border: 1px solid var(--accent-purple);
        }
        input[type="range"]::-webkit-slider-thumb {
            -webkit-appearance: none;
            appearance: none;
            width: 24px;
            height: 24px;
            background: var(--accent-cyan);
            cursor: pointer;
            border-radius: 50%;
            border: 2px solid var(--bg-dark-void);
            box-shadow: 0 0 8px var(--border-glow);
        }
        input[type="range"]::-moz-range-thumb {
            width: 24px;
            height: 24px;
            background: var(--accent-cyan);
            cursor: pointer;
            border-radius: 50%;
            border: 2px solid var(--bg-dark-void);
            box-shadow: 0 0 8px var(--border-glow);
        }
        .slider-value {
            font-family: var(--font-tech);
            font-size: 1.3rem;
            min-width: 100px;
            text-align: right;
            color: var(--accent-cyan);
            text-shadow: 0 0 5px var(--accent-cyan);
        }

        @media (max-width: 768px) {
            .slider-value { min-width: 80px; font-size: 1.1rem; }
        }

        .location-grid { display: flex; flex-wrap: wrap; gap: 0.9rem; }
        .location-tag {
            padding: 0.6rem 1.2rem;
            background: rgba(0,0,0,0.4);
            border: 2px solid var(--accent-purple);
            border-radius: 25px;
            cursor: pointer;
            transition: all 0.3s ease;
            font-size: 0.95rem;
            box-shadow: 0 0 5px rgba(122, 47, 255, 0.3);
        }
        .location-tag:hover, .location-tag.selected {
            background: linear-gradient(135deg, var(--accent-purple), var(--interactive-highlight));
            color: #fff;
            box-shadow: 0 0 15px var(--accent-purple);
            transform: translateY(-2px);
        }

        @media (max-width: 768px) {
            .location-tag { padding: 0.5rem 1rem; font-size: 0.9rem; }
        }
    </style>
</head>

<body>

<div id="difficulty-selector" class="holographic-panel">
    <h2>// 转生协议初始化</h2>
    <p>凡人，选择你新人生的难度吧！不同的难度将决定你的初始构筑点数。</p>
    <div class="difficulty-options">
        <button class="action-btn" data-difficulty="极简" data-points="102">极简模式 (102 点)</button>
        <button class="action-btn" data-difficulty="简单" data-points="35">简单模式 (35 点)</button>
        <button class="action-btn" data-difficulty="普通" data-points="30">普通模式 (30 点)</button>
        <button class="action-btn" data-difficulty="困难" data-points="25">困难模式 (25 点)</button>
        <button class="action-btn" data-difficulty="凡人" data-points="20">凡人模式 (20 点)</button>
    </div>
</div>

<div class="genesis-folio holographic-panel" id="genesis-folio">
    <header class="folio-header"><h1>身份构筑</h1></header>
    <div class="folio-content">
        <section class="folio-section">
            <h3>// 核心识别码</h3>
            <div class="form-grid">
                <div class="form-group">
                    <label for="char-name">姓名</label>
                    <input type="text" id="char-name" class="form-input" placeholder="输入代号">
                </div>
                <div class="form-group">
                    <label for="char-age">年龄</label>
                    <input type="number" id="char-age" class="form-input" placeholder="输入生理年龄">
                </div>
                <div class="form-group">
                    <label>转生者</label>
                    <div class="checkbox-group">
                        <input type="checkbox" id="char-reincarnated" checked>
                        <label for="char-reincarnated">是转生者</label>
                    </div>
                </div>
                <div class="form-group">
                    <label for="char-race">种族</label>
                    <select id="char-race" class="form-select"></select>
                </div>
                <div class="form-group">
                    <label for="char-gender">性别</label>
                    <select id="char-gender" class="form-select"></select>
                </div>
                <div class="form-group">
                    <label for="char-faith">信仰</label>
                    <input type="text" id="char-faith" class="form-input" placeholder="例如: 欲望女士, 正义女神...">
                    <small>可多选，用逗号分隔</small>
                </div>
                <div class="form-group">
                    <label for="char-profession">职业</label>
                    <input type="text" id="char-profession" class="form-input" placeholder="例如: 战士, 法师, 女巫...">
                    <small>可多选，用逗号分隔</small>
                </div>
                <div class="form-group">
                    <label for="char-adventurer-rank">冒险者等级</label>
                    <select id="char-adventurer-rank" class="form-select"></select>
                </div>
            </div>
        </section>

        <section class="folio-section">
            <h3>// 基础属性</h3>
            <div class="attribute-header">
                <div class="points-display">剩余构筑点: <span id="points-display">25</span></div>
                <div class="power-tier-container">
                    <div class="power-tier-display" id="power-tier-display">力量阶位: 学徒</div>
                    <div class="tier-comment" id="tier-comment">你刚刚踏入超凡的门槛，虽然已经超越了普通人，但在这个充满危险的世界里，你仍需谨慎前行，不断积累经验与力量。</div>
                </div>
            </div>
            <p style="color: var(--text-secondary); font-size: 0.85rem; margin-top: -0.5rem; margin-bottom: 1.2rem;">属性值范围 7-18。基础值 10，消耗 0 点。</p>
            <div class="attribute-grid" id="attributes-grid"></div>
            <div class="slider-group">
                <label for="money-slider">剩余点数转换为启动资金 (1 点 = 1 魔晶币)</label>
                <div class="slider-container">
                    <input type="range" id="money-slider" min="0" max="25" value="0">
                    <span class="slider-value" id="money-value">0 魔晶币</span>
                </div>
            </div>
        </section>

        <section class="folio-section">
            <h3>// 冒险者认证</h3>
            <div class="adventurer-rank-container">
                <div class="adventurer-rank-display" id="adventurer-rank-display-section">冒险者等级: 无</div>
                <div class="rank-comment" id="rank-comment">未注册冒险者协会，或选择不以冒险者身份行动。这不代表你弱小，只是你尚未踏入那个充满财富与危险的体系。</div>
            </div>
        </section>

        <section class="folio-section">
            <h3>// 个人特化</h3>
            <div class="form-grid" style="grid-template-columns: 1fr;">
                <div class="form-group">
                    <label for="char-abilities">能力</label>
                    <small style="margin-bottom: 0.5rem; display: block;">
                        可包含魔法（如火球术治疗术）种族天赋（如黑暗视觉飞行）职业技能（如潜行说服）等。可多行填写，每行一项。
                    </small>
                    <div class="input-with-button">
                        <textarea id="char-abilities" class="form-textarea" placeholder="例如:&#10;火球术(塑能) - 召唤火焰攻击敌人&#10;黑暗视觉(精灵) - 在黑暗中视物&#10;潜行(盗贼) - 无声移动"></textarea>
                        <button class="dice-btn" id="random-abilities-btn" title="随机生成能力">🎲</button>
                    </div>
                </div>
            </div>
        </section>

        <section class="folio-section">
            <h3>// 降生信标</h3>
            <div class="location-grid" id="location-grid"></div>
        </section>

        <section class="folio-section">
            <h3>// 自定义烙印</h3>
            <textarea id="custom-settings" class="form-textarea" rows="5" placeholder="在此输入任何个人设定，包括但不限于外貌、性格、背景故事、个人物品或特殊设定..."></textarea>
        </section>

        <button class="action-btn" id="finalize-btn" style="width:100%; font-size: 1.5rem; padding: 1.2rem;">// 转生启动！</button>
    </div>
</div>

<script>
document.addEventListener('DOMContentLoaded', () => {

    const appState = {
        totalPoints: 25,
        remainingPoints: 25,
        attributes: { '力量': 10, '敏捷': 10, '体质': 10, '智力': 10, '感知': 10, '魅力': 10 },
        pointsForMoney: 0,
        selectedLocation: null,
    };

    const pointCost = { 7: -4, 8: -2, 9: -1, 10: 0, 11: 1, 12: 2, 13: 3, 14: 5, 15: 7, 16: 10, 17: 13, 18: 17 };
    const attributeNames = ['力量', '敏捷', '体质', '智力', '感知', '魅力'];
    const races = ['人类', '女巫', '精灵', '矮人', '亚人', '龙娘', '翼人', '人偶', '苍白精灵', '灰矮人', '吸血鬼', '天使', '兽人', '哥布林'];
    const genders = ['男', '女'];
    const adventurerRanks = [
        { value: '无', label: '无' },
        { value: 'F', label: 'F - 见习者' },
        { value: 'E', label: 'E - 摸索者' },
        { value: 'D', label: 'D - 合格者' },
        { value: 'C', label: 'C - 资深者' },
        { value: 'B', label: 'B - 精英' },
        { value: 'A', label: 'A - 英雄' },
        { value: 'S', label: 'S - 神话' }
    ];
    const locations = [
        { name: '中央大平原', desc: '帝国的文明心脏，秩序与进步的象征。' },
        { name: '西部破碎之地', desc: '纷争地带，佣兵冒险者与流亡者的乐园。' },
        { name: '南部地区', desc: '贸易联邦的根据地大陆的贸易与金融中心。' },
        { name: '北方冻土', desc: '严酷的极寒之地兽人与哥布林部落的家园。' },
        { name: '东方沙海与雨林', desc: '遍布死灵王朝遗迹的财富与死亡交织之地。' },
        { name: '远西大陆', desc: '充满未知与失落技术的蛮荒之地。' },
        { name: '地底世界', desc: '永暗的地下边疆，遵循残酷的丛林法则。' }
    ];

    const abilityPool = [
        '火球术(塑能) - 召唤火焰球体攻击敌人',
        '治疗术(神术) - 治愈伤口恢复生命力',
        '黑暗视觉(精灵/矮人) - 在完全黑暗中正常视物',
        '飞行(翼人/龙娘) - 依靠翅膀在空中飞行',
        '魔法抗性(龙娘) - 天生抵抗魔法效果',
        '潜行(盗贼) - 无声无息地移动',
        '说服(诗人) - 用言语影响他人',
        '锻造(矮人) - 制作精良的武器装备',
        '精液汲取(女巫/吸血鬼) - 通过摄取精液补充魔力',
        '剑术精通(战士) - 熟练使用各类剑类武器'
    ];

    const tierComments = {
        '学徒': '你刚刚踏入超凡的门槛，虽然已经超越了普通人，但在这个充满危险的世界里，你仍需谨慎前行，不断积累经验与力量。',
        '正式': '你已掌握了足以安身立命的专业技能，是社会运转的中坚力量，能够独立处理城镇周边的常规威胁。',
        '精英': '你在各自领域中出类拔萃，实力足以应对区域性的危机，是各大势力争相拉拢的核心战力。',
        '大师': '你站在凡人巅峰，名字足以在王国间流传，行动能够影响历史的走向，是行走的战略武器。',
        '传奇': '你踏入了半神的领域，是活着的传说。财富与名声对你而言已是寻常，你的存在本身就足以改变世界的格局。',
        '天灾': '你是规格之外的存在，是行走于大地的神话。一举一动都可能对整个世界造成毁灭性的灾难，连神明都不得不正视你的威胁。'
    };

    const rankComments = {
        '无': '未注册冒险者协会，或选择不以冒险者身份行动。这不代表你弱小，只是你尚未踏入那个充满财富与危险的体系。',
        'F': '你刚刚注册成为冒险者，是协会生态系统的基石。你的生活围绕着城镇内的基础委托展开，每一次完成任务都是信心的建立。',
        'E': '你已初出茅庐，能够处理城镇周边的低威胁任务，开始尝试组建固定的小队，学习如何与同伴协同作战。',
        'D': '你是具备独立处理常规威胁能力的合格冒险者，是协会的中坚力量，守护商路清剿哥布林哨站的主力。',
        'C': '你是经验丰富的冒险者，通常在某个领域小有名气，有能力领导小队执行较为复杂的任务，如探索古代遗迹的浅层区域。',
        'B': '你在某个地区或领域内享有盛誉，实力足以影响局部战局。地方领主会将你奉为座上宾，接受的委托往往直接来自贵族或领主。',
        'A': '你是活着的传奇，实力与功绩足以与国家级的英雄媲美。你的名字在王国间流传，每一次行动都备受关注，决定能够改变历史的走向。',
        'S': '你是规格之外的存在，力量与事迹已经达到了神话的领域。你可能是传奇强者历史贡献者，或是完成了足以被载入史册伟业的奇迹工作者。'
    };

    const DOM = {
        difficultySelector: document.getElementById('difficulty-selector'),
        genesisFolio: document.getElementById('genesis-folio'),
        difficultyOptions: document.querySelectorAll('.difficulty-options button'),
        raceSelect: document.getElementById('char-race'),
        genderSelect: document.getElementById('char-gender'),
        adventurerRankSelect: document.getElementById('char-adventurer-rank'),
        attributesGrid: document.getElementById('attributes-grid'),
        pointsDisplay: document.getElementById('points-display'),
        powerTierDisplay: document.getElementById('power-tier-display'),
        tierComment: document.getElementById('tier-comment'),
        adventurerRankDisplaySection: document.getElementById('adventurer-rank-display-section'),
        rankComment: document.getElementById('rank-comment'),
        moneySlider: document.getElementById('money-slider'),
        moneyValue: document.getElementById('money-value'),
        locationGrid: document.getElementById('location-grid'),
        finalizeBtn: document.getElementById('finalize-btn'),
        randomAbilitiesBtn: document.getElementById('random-abilities-btn'),
        abilitiesTextarea: document.getElementById('char-abilities'),
    };

    function calculateTotalCost() {
        return attributeNames.reduce((total, attr) => total + pointCost[appState.attributes[attr]], 0);
    }

    function updateUI() {
        const cost = calculateTotalCost();
        appState.remainingPoints = appState.totalPoints - cost - appState.pointsForMoney;
        DOM.pointsDisplay.textContent = appState.remainingPoints;

        DOM.moneySlider.max = appState.totalPoints - cost;
        DOM.moneyValue.textContent = `${appState.pointsForMoney} 魔晶币`;

        attributeNames.forEach(attr => {
            const val = appState.attributes[attr];
            const plusBtn = document.getElementById(`plus-${attr}`);
            const minusBtn = document.getElementById(`minus-${attr}`);

            const costToIncrease = (pointCost[val + 1] - pointCost[val]) || 999;
            if (plusBtn) plusBtn.disabled = val >= 18 || appState.remainingPoints < costToIncrease;
            if (minusBtn) minusBtn.disabled = val <= 7;
        });

        // Update power tier
        const totalAttr = attributeNames.reduce((sum, attr) => sum + appState.attributes[attr], 0);
        const avgAttr = totalAttr / attributeNames.length;
        let tier = '学徒';
        if (avgAttr > 27) tier = '天灾';
        else if (avgAttr > 24) tier = '传奇';
        else if (avgAttr > 19) tier = '大师';
        else if (avgAttr > 16) tier = '精英';
        else if (avgAttr > 13) tier = '正式';

        DOM.powerTierDisplay.textContent = `力量阶位: ${tier}`;
        DOM.powerTierDisplay.className = `power-tier-display power-tier-${tier}`;
        DOM.tierComment.textContent = tierComments[tier];
    }

    function updateAdventurerRankComment() {
        const rank = DOM.adventurerRankSelect.value;
        DOM.adventurerRankDisplaySection.textContent = `冒险者等级: ${rank}`;
        DOM.adventurerRankDisplaySection.className = `adventurer-rank-display adventurer-rank-${rank}`;
        DOM.rankComment.textContent = rankComments[rank];
    }

    function changeAttribute(attr, delta) {
        const oldValue = appState.attributes[attr];
        const newValue = oldValue + delta;
        if (newValue < 7 || newValue > 18) return;

        const oldCost = pointCost[oldValue];
        const newCost = pointCost[newValue];
        const costChange = newCost - oldCost;

        if (appState.remainingPoints - costChange >= 0) {
            appState.attributes[attr] = newValue;
            document.getElementById(`value-${attr}`).textContent = newValue;
            updateUI();
        }
    }

    function initialize() {
        // Populate dropdowns
        races.forEach(r => DOM.raceSelect.add(new Option(r, r)));
        genders.forEach(g => DOM.genderSelect.add(new Option(g, g)));
        adventurerRanks.forEach(ar => DOM.adventurerRankSelect.add(new Option(ar.label, ar.value)));

        // Build attribute controls
        attributeNames.forEach(attr => {
            const item = document.createElement('div');
            item.className = 'attribute-item';
            item.innerHTML = `
                <span class="attr-name">${attr}</span>
                <div class="attr-controls">
                    <button id="minus-${attr}">-</button>
                    <span class="attr-value" id="value-${attr}">10</span>
                    <button id="plus-${attr}">+</button>
                </div>
            `;
            DOM.attributesGrid.appendChild(item);
            document.getElementById(`plus-${attr}`).addEventListener('click', () => changeAttribute(attr, 1));
            document.getElementById(`minus-${attr}`).addEventListener('click', () => changeAttribute(attr, -1));
        });

        // Build location tags
        locations.forEach(loc => {
            const tag = document.createElement('div');
            tag.className = 'location-tag';
            tag.textContent = loc.name;
            tag.title = loc.desc;
            tag.addEventListener('click', () => {
                if (appState.selectedLocation) { appState.selectedLocation.classList.remove('selected'); }
                tag.classList.add('selected');
                appState.selectedLocation = tag;
            });
            DOM.locationGrid.appendChild(tag);
        });

        // Event listeners
        DOM.difficultyOptions.forEach(btn => {
            btn.addEventListener('click', () => {
                appState.totalPoints = parseInt(btn.dataset.points, 10);
                appState.pointsForMoney = 0;
                DOM.moneySlider.value = 0;
                attributeNames.forEach(attr => { appState.attributes[attr] = 10; document.getElementById(`value-${attr}`).textContent = 10; });
                updateUI();
                DOM.difficultySelector.style.display = 'none';
                DOM.genesisFolio.style.display = 'flex';
            });
        });

        DOM.moneySlider.addEventListener('input', (e) => {
            appState.pointsForMoney = parseInt(e.target.value, 10);
            updateUI();
        });

        DOM.adventurerRankSelect.addEventListener('change', updateAdventurerRankComment);

        DOM.randomAbilitiesBtn.addEventListener('click', () => {
            const count = Math.floor(Math.random() * 3) + 2; // 2-4 abilities
            const selected = [];
            const poolCopy = [...abilityPool];
            for (let i = 0; i < count && poolCopy.length > 0; i++) {
                const idx = Math.floor(Math.random() * poolCopy.length);
                selected.push(poolCopy.splice(idx, 1)[0]);
            }
            DOM.abilitiesTextarea.value = selected.join('\n');
        });

        DOM.finalizeBtn.addEventListener('click', () => {
            const profile = {
                '姓名': document.getElementById('char-name').value || '未定',
                '年龄': document.getElementById('char-age').value || '未知',
                '转生者': document.getElementById('char-reincarnated').checked ? '是' : '否',
                '种族': DOM.raceSelect.value,
                '性别': DOM.genderSelect.value,
                '信仰': document.getElementById('char-faith').value || '无',
                '职业': document.getElementById('char-profession').value || '无',
                '冒险者等级': DOM.adventurerRankSelect.value,
                '属性': appState.attributes,
                '力量阶位': DOM.powerTierDisplay.textContent.split(': ')[1],
                '启动资金': `${appState.pointsForMoney} 魔晶币`,
                '能力': DOM.abilitiesTextarea.value || '无',
                '出生地': appState.selectedLocation ? appState.selectedLocation.textContent : '未知',
                '自定义设定': document.getElementById('custom-settings').value || '无'
            };

            let profileString = "角色档案:\n";
            for (const [key, value] of Object.entries(profile)) {
                if (key === '属性') {
                    profileString += `属性: ${Object.entries(value).map(([k, v]) => `${k} ${v}`).join(', ')}\n`;
                } else {
                    profileString += `${key}: ${value}\n`;
                }
            }

            const command = `Admin:请为玩家撰写一段身临其境的开场,根据下列档案进行完全而全面的变量更新。故事需要巧妙地融入以下角色档案中的信息,并最终引出一个需要玩家做出选择或行动的简单情境。\n\n${profileString}`;

            navigator.clipboard.writeText(command).then(() => {
                alert('角色档案已生成并复制到剪贴板！请粘贴到聊天框开始你的旅程。');
                DOM.finalizeBtn.textContent = '// 已复制！';
                DOM.finalizeBtn.disabled = true;
            }).catch(err => {
                alert('自动复制失败，请手动复制以下内容:\n\n' + command);
                console.error('复制失败: ', err);
            });
        });

        updateUI();
        updateAdventurerRankComment();
    }

    initialize();
});
</script>

</body>
</html>
