entries.content:
{
  "race_name": "矮人",
  "summary": "一个心灵手巧无酒不欢且极其记仇的工匠种族。以氏族为社会核心，男女外貌差异巨大，广泛分布于地表与山脉城市中。",
  "physical_traits": {
    "appearance": "男女差异显著。男性身材敦实，以保养长须为荣，胡子长短代表年龄。女性身材相对纤细，性特征明显，无须。",
    "lifespan": "平均在200岁时进入老年，并在300岁左右逝世。",
    "height_range": {
      "min": "1.2米",
      "max": "1.4米"
    },
    "development": "12岁后身体便停止发育，并在20岁时成年。"
  },
  "abilities_and_traits": {
    "core_ability": [
      "天生的心灵手巧的工匠，艺术造诣高。",
      "能够轻易分辨并找出矿物的位置。",
      "力量较人类更大。",
      "对酒精有极高的耐性。"
    ]
  },
  "society_and_culture": {
    "distribution": "常见种族，数量比精灵略多，遍布世界各处。",
    "settlements": "大型氏族居住于山脉内的城市，拥有独特科技；小型氏族则居住在地表城市。",
    "social_structure": "以氏族制度为社会核心。",
    "special_notes": [
      "在山脉内挖掘时，有可能会发现过往纪元的遗迹或通往地底世界的通道。",
      "每一个矮人氏族都持有一本'仇恨之书'，用以记录所有受到的侮辱与亏欠。任何被记入书中的仇恨都必须得到清算，否则便是整个氏族的耻辱。",
      "极度厌恶任何关于身高的玩笑，将其视为最严重的冒犯，足以引发流血冲突并被记入'仇恨之书'。"
    ]
  },
  "sub_races": [
    {
      "name": "灰矮人",
      "summary": "矮人在地底的亚种，肤色白皙，社会结构中存在奴隶制，且更倾向于使用魔法。有着独特的符文科技",
      "key_features": {
        "appearance": "肤色比地表亲族更为白皙。",
        "society": "实行氏族制与奴隶制，多数族人居住在同一城市，并分为五大氏族。是苍白精灵偏爱的奴隶种类之一。",
        "abilities": "能力与地表矮人无太大区别，但更愿意接纳并使用魔法。"
      }
    }
  ]
}

