{
  "race_name": "血族",
  "summary": "一种由死灵法师创造的貌美女性不死生物，自称血族。她们力量强大，掌握精液魔法，社会结构复杂，以氏族和派系划分，并存在着严格的代数血脉限制。",
  "physical_traits": {
    "appearance": "外貌皆为美貌漂亮的女性，具有极强的魅惑力。",
    "lifespan": "理论上无上限，但代数越高寿命越短。初代真祖为无限寿命，后代需通过沉眠延长生命。",
    "height_range": {
      "note": "身高与人类相仿。"
    },
    "gender": "仅有女性。"
  },
  "abilities_and_traits": {
    "core_ability": [
      "能够使用精液魔法（自称液体魔法）。",
      "可操控蝙蝠或自身变形为蝙蝠群。",
      "拥有黑暗视觉。",
      "能够操控不死生物，或通过法术转化凡人与尸骨。",
      "力量强大，仅能被银所伤。",
      "可通过'初拥'制造后代或通过简化仪式制造食尸鬼。"
    ],
    "racial_quirk": {
      "generational_decay": "能力强度与代数成反比，甚至会因为代数的增长而缺失各种能力。从第一代真祖算起，血脉传承至第16代为止。第17代的后裔将极度劣化，难以维持理智，其初拥也只能制造出无智的食尸鬼。",
      "generational_advancement": "低代数血族可以接受更高代数（即代数数字更小）血族的再次初拥，从而提升自己的代数，强化力量。例如，一位16代血族若被14代血族再次初拥，便会成为15代；若有幸被真祖初拥，则可以直接成为第二代。这是血族内部最重要的力量提升途径。"
    },
    "weaknesses": "除真祖外，皆惧怕阳光。暴露在阳光下会导致防御力下降，甚至直接死亡。"
  },
  "society_and_culture": {
    "distribution": "总数不超过千人。",
    "naming_convention": "所有成员自称为'血族'，并极度厌恶'吸血鬼'这一称谓，视其为来自凡人的蔑称。",
    "social_structure": "以议会氏族制为核心，共十三个氏族，分别对应十三位真祖。",
    "political_factions": [
      {
        "name": "秘党",
        "clans": 7,
        "description": "最大的保守派系，由七氏族族长组成议会，推举年长者为议会长。在阿尔比恩帝国首都渗透为贵族并掌控地下网络。"
      },
      {
        "name": "叛党",
        "clans": 4,
        "description": "以推翻长老统治争取自由平等为目标，吸引新生代血族。是贸易联盟的四大主导家族。"
      },
      {
        "name": "隐世会",
        "clans": 2,
        "description": "最早脱离死灵法师控制的氏族，藏匿于世界各地对同族斗争持旁观态度。"
      }
    ]
  }
}

