entries.content:
{
  "race_name": "天使",
  "summary": "由神明直接创造的万能助手与神国护卫。她们是外貌优美能力强大的异界种族，以精液代替传统食粮。其社会虽有明确的职责阶层划分，但个体间人格完全平等。她们通常居于神国，仅在凡间出现重大危机时才会降临，是神明意志在地面的延伸。",
  "physical_traits": {
    "appearance": "外貌精致优美，拥有作为力量源泉与敏感带的光翼与光环。阶位越高，光翼数量越多，光环越华丽。",
    "lifespan": "没有寿命限制，不会自然衰老或死亡。",
    "height_range": {
      "min": "1.2米",
      "max": "1.8米"
    },
    "clothing_style": "以科技感的紧身衣或战斗服为素体，外挂风格化的装甲与武器，整体呈现机娘风格。",
    "visual_diversity": "不同神明麾下的天使，其光翼光环的颜色形态以及服饰主色调均不相同，以此彰显其归属。例如，正义女神阿斯特莱雅的天使以纯白与金色为主调，光环带有天平装饰；而欲望女士莉莉丝的天使则以暗紫与绯红为主调，光环呈荆棘形态。"
  },
  "abilities_and_traits": {
    "core_ability": [
      "基础身体与魔法能力普遍高于绝大多数凡人种族。",
      "能够熟练运用通用魔法与精液魔法。"
    ],
    "reproduction": "无法自然繁衍。新生的天使由神明直接创造，或由最狂热信徒的灵魂在神国中重塑而成。",
    "racial_quirk": "将精液视为一种美味饮品，不同种族的精液拥有不同的'风味'。"
  },
  "society_and_culture": {
    "distribution": "绝大多数天使居住在各自侍奉神明的神国之中，罕见于凡间。凡间的浮空城'天穹之眼'是她们应对危机时的一个前哨站。",
    "social_structure": "天使社会存在九个阶层，但这仅是基于职责与能力进行的明确分工，所有天使在人格与地位上完全平等，不存在阶级压迫。",
    "mundane_interaction": "通常仅在应对足以威胁大陆平衡的重大危机时，才会以军团形式降临。但也有少数天使因任务意外好奇心或被捕获等原因滞留凡间，她们强大的力量与异界的美貌，使其成为奴隶市场上价值连城的猎物。",
    "hierarchy": [
      {
        "name": "天使",
        "wings": "一对",
        "halo": "朴素光环",
        "role": "构成天使军团基础作战与勤务单位。"
      },
      {
        "name": "大天使",
        "wings": "一对",
        "halo": "带有基础纹饰的光环",
        "role": "天使军团中的小队指挥官与士官。"
      },
      {
        "name": "权天使",
        "wings": "一对",
        "halo": "带有其神明象征符号的光环",
        "role": "负责管理神国特定领域或作为神明使者出现在凡间。"
      },
      {
        "name": "能天使",
        "wings": "两对",
        "halo": "简洁而华丽的光环",
        "role": "神国与重要圣地的主要戍卫部队。"
      },
      {
        "name": "力天使",
        "wings": "两对",
        "halo": "象征其神明权能的光环",
        "role": "作为神明展现奇迹的执行者或高级军团的核心力量。"
      },
      {
        "name": "主天使",
        "wings": "两对",
        "halo": "繁复华丽的光环",
        "role": "负责管理天使族群的内部秩序与人事调动。"
      },
      {
        "name": "座天使",
        "wings": "三对",
        "halo": "如同王冠般复杂的光环",
        "role": "神国的记录者与通讯枢纽，传递神明的意志。"
      },
      {
        "name": "智天使",
        "wings": "三对",
        "halo": "如同星轨般复杂的光环",
        "role": "神国的仲裁者与最终防御力量，是神明最信赖的护卫。"
      },
      {
        "name": "炽天使",
        "wings": "三对",
        "halo": "燃烧着神圣火焰的冠冕状光环",
        "role": "最高阶级，直接侍奉于神明身侧，是神明意志最直接的代行者。"
      }
    ]
  }
}

