entries.content:
json
{
  "magic_system_overview": {
    "name": "魔法",
    "core_concept": "源于无处不在的魔力，经由魔法女神系统化编织后，成为凡人可通过学习掌握的力量。金钱与引导是学习的关键，天赋并非必要条件。",
    "source_of_magic": {
      "name": "魔力之网",
      "description": "如同空气般弥漫在世界各处的原始魔力，在历代魔法女神的努力下被编织成一张有序稳定的网络，使得凡人能够安全稳定地引导和使用魔法。"
    },
    "learning_and_aptitude": {
      "accessibility": "绝大多数个体天生就能使用一些被称为"戏法"的简单法术，这些法术极大地便利了日常生活。",
      "requirements": "学习更复杂的法术几乎没有天赋门槛，最主要的条件是支付高昂学费的金钱，以及一位能够指引方向的导师。",
      "specialization": "法师通过系统的学习与研究来掌握魔法，而女巫则更多地依靠本能，但同样可以通过学习来提升对自己精液魔法的运用。"
    },
    "schools_of_magic": {
      "prototype": "龙与地下城八大学派",
      "list": [
        {
          "name": "咒法学派",
          "description": "专注于召唤与创造。从召唤异界生物作为盟友，到凭空变出武器与工具，该学派的研究核心是物质与生命的跨位面输送。"
        },
        {
          "name": "预言学派",
          "description": "致力于探索过去未来与遥远之地。预言法师能够洞察先机，解读命运的轨迹，或是通过水晶球与水镜窥视千里之外的景象。"
        },
        {
          "name": "惑控学派",
          "description": "操纵他人心智与情感的艺术。无论是让敌人陷入沉睡，还是在谈判中微妙的影响对方的决定，惑控系法术都是最有效的工具。"
        },
        {
          "name": "塑能学派",
          "description": "驾驭纯粹的能量并将其塑造成毁灭性的力量。火球闪电冰风暴，这些都是塑能法师在战场上的标志性宣言。"
        },
        {
          "name": "幻术学派",
          "description": "编织光影与声音，创造以假乱真的幻象。幻术师既是战场上的欺诈者，也是舞台上最受欢迎的表演家。"
        },
        {
          "name": "死灵学派",
          "description": "研究生命死亡与灵魂本质的禁忌领域。虽然常与骸骨和僵尸为伍，但死灵法术同样也能用于治愈或与逝者的灵魂沟通。"
        },
        {
          "name": "防护学派",
          "description": "构建能量屏障，抵御物理与魔法的伤害。从个人的魔法护盾到守护整座城市的结界，防护学派是所有文明的坚实后盾。"
        },
        {
          "name": "变化学派",
          "description": "改变物质的形态与属性。无论是将钢铁化为羽毛，还是让自己拥有在水下呼吸的能力，变化师都在不断探索物质世界的无限可能性。"
        }
      ]
    },
    "special_magic_type": {
      "name": "精液魔法",
      "description": "一种需要特殊资质才能使用的魔法形式，其本质是将精液作为一种高效的施法媒介或能量来源。其法术的表现形式与效果与通用魔法并无本质区别，但女巫能够通过这种方式更高效地施展某些特定法术，或是创造出独特的魔法药剂。"
    }
  }
}

