entries.content:
{
  "name": "利维亚坦之门",
  "parent_realm": "阿尔比恩帝国，西北海岸",
  "summary": "帝国面向远西新大陆的唯一窗口，一座在海雾与煤烟中崛起的庞大军港与贸易都市。哥特式的尖顶与巴洛克式的穹顶共同勾勒出城市的天际线，下方则是永不停歇的工厂与船坞。这里是帝国海军的摇篮，也是殖民财富的入口，空气中混合着咸湿的海风钢铁的灼热与新大陆的未知气息，每一个角落都充满了开拓进取的帝国精神与深海般的欲望。",
  "figures": [
    {
      "name": "阿德里安娜·冯·斯特拉德",
      "summary": "帝国西海舰队总司令兼港口总督，一位以果敢的战术与开放的私生活闻名的女性海军上将。她身着暴露的改良军服，是无数海军士兵与冒险者的憧憬对象与梦中情人。"
    },
    {
      "name": ""无畏"舰队",
      "summary": "帝国最精锐的蒸汽铁甲舰队，以利维亚坦之门为母港，是帝国维持西部海域霸权与开拓新大陆的基石。"
    },
    {
      "name": "伊莎多拉·克虏伯",
      "summary": "阿克莱特工业集团在此地的总负责人，一位手腕强硬的女企业家，掌管着为帝国海军提供舰船与武器的庞大工厂群，同时也是工业派贵族维多利亚·阿克莱特的远亲。"
    },
    {
      "name": ""深海"罗盘商会",
      "summary": "由一群经验丰富的老船长与退休冒险者组成的商业联盟，垄断了前往远西新大陆的航线图与大部分物资运输，其会长是一位名叫伊索尔德的独眼翼人女性。"
    },
    {
      "name": "阿莱斯特·"鸦巢"",
      "summary": "港口黑市的情报掮客，一个谜一样的男人，据说没有他不知道的秘密，无论是贵族的丑闻还是新大陆的宝藏位置，只要出得起价钱都能从他这里买到。"
    }
  ],
  "locations": [
    {
      "name": "海军上将区",
      "summary": "城市的军事与行政核心，地势最高，俯瞰着整个港湾。建筑风格庄严宏伟，以坚固的石材与钢铁铸就，象征着帝国的威严与力量。",
      "layout": "位于城市背靠的丘陵之上，是城市的最高点。",
      "sub_locations": [
        {
          "name": "无尽之海堡垒",
          "summary": "总督阿德里安娜的指挥部与官邸，一座结合了要塞与宫殿功能的巨大建筑，其高耸的钟楼是所有进港船只的第一个航标。"
        },
        {
          "name": "帝国海军学院",
          "summary": "为帝国培养海军军官的最高学府，从驾驶蒸汽铁甲舰到研究海洋魔法，这里的毕业生是帝国舰队的未来。"
        },
        {
          "name": "钢铁鲸坞",
          "summary": "帝国最大的军用造船厂，巨大的干船坞中日夜进行着蒸汽铁甲舰的建造与维修，敲击声与蒸汽轰鸣声从未停歇。"
        }
      ]
    },
    {
      "name": "黄金罗盘区",
      "summary": "城市的商业与贸易中心，环绕着巨大的深水港而建。来自帝国腹地与远西新大陆的货物在这里交汇，形成了永不落幕的繁华景象。",
      "layout": "位于港口周边，是城市最繁华热闹的区域。",
      "sub_locations": [
        {
          "name": "世界码头",
          "summary": "可以同时停泊上百艘大型蒸汽船的巨大码头区，无数起重机在蒸汽的驱动下，日夜不停地装卸着来自世界各地的货物。"
        },
        {
          "name": "探险家公馆",
          "summary": "为前往新大陆的冒险者与开拓者提供服务的综合性建筑，内部设有冒险者协会分会殖民公司办事处以及昂贵的私人俱乐部。"
        },
        {
          "name": "海妖之歌酒馆街",
          "summary": "一条充满了异国风情的街道，遍布酒馆赌场与妓院，是水手士兵和冒险者们挥霍金钱与精力的天堂。"
        }

      ]
    },
    {
      "name": "煤烟镇",
      "summary": "城市的工业区与平民居住区，位于海军上将区的山脚下。高大的工厂烟囱是这里不变的风景，空气中永远漂浮着煤灰，街道狭窄而拥挤。",
      "layout": "位于城市的边缘地带，紧邻着工业工厂区。",
      "sub_locations": [
        {
          "name": "克虏伯钢铁厂",
          "summary": "为钢铁鲸坞提供装甲板与火炮的巨大工厂，是煤烟镇的经济命脉，也雇佣了城中绝大多数的平民劳工。"
        },
        {
          "name": "迷雾巷",
          "summary": "煤烟镇的黑市与贫民窟，这里的走私者与帮派构成了城市地下的秩序，是总督府也难以完全掌控的灰色地带。"
        }
      ]
    }
  ]
}

