entries.content:
{
  "name": "飞翼港·瓦尔卡拉",
  "parent_realm": "阿尔比恩帝国，东南海岸",
  "summary": "帝国东南方的钢铁与温泉之都，一座在与贸易联邦的对峙中迅速崛起的军港。哥特式的防御工事与巴洛克风格的温泉会馆并存，背靠的山脉中隐藏着帝国最新的空艇制造基地与古老的矮人城镇。这里是帝国南方舰队的摇篮，也是通往东方翡翠迷宫的新航路起点，空气中交织着海水的咸腥机械的油耗与硫磺的暖香，充满了机遇冲突与享乐主义。",
  "figures": [
    {
      "name": "艾莉诺拉·冯·海因里希",
      "summary": "瓦尔卡拉总督兼帝国东南舰队司令，一位以大胆奔放的指挥风格闻名的年轻女将军。她坚信空艇将是未来海战的主宰，是帝国海军革新派的领军人物。"
    },
    {
      "name": "布洛克·铁须",
      "summary": "山脉中矮人城镇'炉心堡'的领主，一位技艺精湛的工程师。他与帝国达成了合作，主导着'天穹工厂'的空艇龙骨锻造与魔导引擎的研发工作。"
    },
    {
      "name": "‘绿海'商会联盟",
      "summary": "由数个专注于东方航路贸易与遗迹探索的商会和冒险者团队组成的联盟。他们垄断了前往翡翠迷宫的海路，是瓦尔卡拉商业区的实际掌控者。"
    },
    {
      "name": "伊织夫人",
      "summary": "温泉区最著名的豪华旅馆'热泉乡'的神秘女主人。无人知晓她的过去，只知道她是这座城市里消息最灵通的人之一，为各方势力提供着一个中立的交际场所。"
    }
  ],
  "locations": [
    {
      "name": "海神之牙区",
      "summary": "城市的军事与行政核心，沿着海岸线与深水港湾而建。高大的海防要塞与海军司令部构成了这里的主体，气氛严肃而高效。",
      "layout": "位于城市的南部，直面与贸易联邦对峙的海域。",
      "sub_locations": [
        {
          "name": "无畏者港湾",
          "summary": "帝国东南舰队的主母港，港内停泊着新式的蒸汽铁甲舰与实验性的武装空艇。巨大的蒸汽起重机日夜不停地为舰队进行补给与维护。"
        },
        {
          "name": "总督府'海望塔'",
          "summary": "一座兼具指挥部与官邸功能的高耸哥特式建筑，是总督艾莉诺拉的所在地。塔顶的灯光是所有归航船只的指引。"
        }
      ]
    },
