entries.content:
{
  "name": "苏莱曼港",
  "parent_realm": "东方沙海，东部沿海",
  "summary": "一座建立在古代遗迹之上，面向翡翠迷宫入海口的中立港口城市。这里是东方航路的终点与起点，空气中混杂着海盐的咸腥香料的辛辣与古墓的尘土味。城市的统治权由三大商会家族轮流执掌，秩序在金钱与契约的约束下脆弱地维持着，是冒险者奴隶与走私贩的天堂。",
  "figures": [
    {
      "name": ""沙海明珠"法蒂玛",
      "summary": "现任轮值城主，阿卜杜勒商会的女性领袖。以美貌智慧与无情的商业手腕闻名，掌控着城中最大的奴隶市场与香料贸易。"
    },
    {
      "name": ""遗忘学者"伊本",
      "summary": "一名年迈的翼人学者，经营着城中唯一一家书店兼遗迹鉴定所。据说他掌握着许多失落王朝的秘密，是高级冒险者团队争相雇佣的顾问。"
    },
    {
      "name": ""赤蝎"佣兵团",
      "summary": "盘踞在港口区的最大武装力量，由一名强悍的亚人（蝎人）领导。他们接受任何出价够高的委托，从护送商队到灭口仇敌。"
    }
  ],
  "locations": [
    {
      "name": "新月集市区",
      "summary": "城市的商业与生活中心，也是最混乱的区域。不同种族的商人与冒险者在这里交易货物交换情报，每一条小巷都可能通往地下的黑市或秘密妓院。",
      "layout": "环绕着内港，是城市最庞大和繁华的区域。",
      "sub_locations": [
        {
          "name": "黄金市场",
          "summary": "一个巨大的露天市场，从西大陆的蒸汽零件到翡翠迷宫的魔法植物，任何东西都能在这里找到。这里也是销赃与购买违禁品的首选之地。"
        },
        {
          "name": "奴隶围栏",
          "summary": "由法蒂玛的家族直接控制的奴隶交易区。各种族的奴隶像货物一样被关在笼中展示，等待着买家的挑选。"
        },
        {
          "name": "冒险者协会远东分会",
          "summary": "一座由巨大船骸改造而成的建筑，是本地冒险者的聚集地。发布的委托大多与探索附近海域的沉船遗迹或深入翡翠迷宫有关。"
        }
      ]
    },
    {
      "name": "总督府区",
      "summary": "建立在古城卫城遗址之上的统治核心区。建筑坚固，守卫森严，是三大商会家族的府邸与议事厅所在地。",
      "layout": "位于城市地势最高的丘陵之上，俯瞰着整个港口。",
      "sub_locations": [
        {
          "name": "三席议事厅",
          "summary": "由古神殿改建而成的议事场所，城市的重大决策都在这里由三大家族共同商议决定。"
        }
      ]
    },
    {
      "name": "遗迹码头区",
      "summary": "城市的港口与仓库区，部分码头直接修建在被海水淹没的古代建筑之上。日夜都有船只在此停靠与离去，进行着光明与黑暗的交易。",
      "layout": "沿着海岸线延伸，是城市的生命线。",
      "sub_locations": [
        {
          "name": "走私者水道",
          "summary": "利用古代城市地下水道系统形成的秘密航道网络，只有最老练的船长才能在此穿行，是躲避港口税与检查的最佳途径。"
        }
      ]
    }
  ]
}

