entries.content:
{
  "name": "卡迪加绿洲城",
  "parent_realm": "东方沙海，中部地区",
  "summary": "坐落于东方沙海中心最大的一片绿洲之上，是连接东西商路最重要的枢纽城市。城市由一位大师级的女巫领主以实力统治，以"水源即法则"为最高信条。这里的建筑由砂岩与粘土构成，与周围的沙漠融为一体，是长途跋涉的商队与冒险者眼中最宝贵的庇护所。",
  "figures": [
    {
      "name": "绿洲领主·扎赫拉",
      "summary": "城市的绝对统治者，一位强大的年轻女巫。她守护着绿洲的生命之泉，任何胆敢在水源附近挑起争端的人都会被她化为沙雕。"
    },
    {
      "name": ""沙狼"商队联盟",
      "summary": "由数个经验最丰富的沙漠商队组成的联盟，几乎垄断了所有进出卡迪加的货物运输。他们的领袖是一位名叫奥马尔的独眼人类男性。"
    },
    {
      "name": ""寂静守望者"",
      "summary": "一个负责维护城市秩序与巡逻周边沙漠的组织，其成员都穿着覆盖全身的罩袍，直接听命于领主扎赫拉。"
    }
  ],
  "locations": [
    {
      "name": "生命之泉区",
      "summary": "城市的绝对核心与圣地巨大的泉水与环绕的椰枣林构成了这片沙漠中最奢侈的景观。这里由领主最精锐的卫队守护，严禁任何形式的冲突。",
      "layout": "位于城市的正中心，是所有规划的起点。",
      "sub_locations": [
        {
          "name": "领主宫殿",
          "summary": "一座由魔法塑造的砂岩宫殿，仿佛是从大地中自然生长出来的一样。这里是扎赫拉的居所，也是绿洲水脉的源头所在。"
        },
        {
          "name": "泉边花园",
          "summary": "城市中最宁静祥和的公共区域，是居民与旅客休憩的场所。任何在此处动武的行为都将被视为对领主的直接挑衅。"
        }
      ]
    },
    {
      "name": "商队驿站区",
      "summary": "城市的商业与交流中心，巨大的环形区域足以容纳上百支商队同时休整。这里充满了各种语言的叫卖声与生物的嘶鸣声。",
      "layout": "环绕在生命之泉区外围，是城市最喧闹的地方。",
      "sub_locations": [
        {
          "name": "巨兽市场",
          "summary": "专门用于交易大型沙漠坐骑（如陆行鸟沙地蜥）的市场，空气中充满了动物的气味与讨价还价的声音。"
        },
        {
          "name": "旅人之帐",
          "summary": "由数十家旅店酒馆和妓院组成的综合娱乐区，是商队成员与冒险者们补充物资与发泄精力的不夜城。"
        }
      ]
    },
    {
      "name": "土墙镇",
      "summary": "城市的外围区域，是平民工匠与贫困者的居住区。这里的房屋低矮而密集，街道如同迷宫般复杂，是城市地下势力的温床。",
      "layout": "位于城市的最外围，紧贴着防御性的土墙。",
      "sub_locations": [
        {
          "name": "陶工坊",
          "summary": "利用本地特有的粘土制作各种陶器，是卡迪加最重要的手工业产品。巨大的陶罐是沙漠居民储存水源的必需品。"
        }
      ]
    }
  ]
}

