entries.content:
{
  "name": "空中庭院·艾瑞瑟尔",
  "parent_realm": "泰拉·米拉比里斯大陆，翡翠迷宫上空",
  "summary": "一座法师纪元时期的浮空城核心遗骸，它如同鬼魅般在翡翠迷宫的云海中无声缓慢漂移。巨大的藤蔓与盘根错节的植物缠绕着精致的白色建筑，构成了一幅静谧而诡异的画卷。这里是失落知识的圣殿，也是自律魔偶的王国。其内部封存着足以颠覆时代的古代技术，但数千年来，只有一位冒险者得以窥其一角并全身而退。",
  "figures": [
    {
      "name": "塔灵·艾瑞瑟尔",
      "summary": "与浮空城同名，主宰之塔的AI核心与守护者，一个以法师学徒形象出现的光影投射体。她遵循着塔主最后的指令——"守护知识，直至传承者出现"，在漫长的岁月中已演化出独特的自我意识，对所有闯入者执行着无情的协议。"
    },
    {
      "name": ""蒸汽先驱"雷金纳德",
      "summary": "历史上唯一被确认成功从艾瑞瑟尔带出资料的S级冒险者。他当年获取的几卷关于能量转换的图纸，直接催生了帝国第一次蒸汽革命。如今他是帝国皇家魔导学院的终身顾问，对那次经历讳莫如深。"
    },
    {
      "name": ""星辰编织者"阿斯塔罗斯",
      "summary": "艾瑞瑟尔的建造者与最后一任主人，一位法师纪元时期伟大的奥术师。他早已在历史中化为尘埃，但其思想与力量依然通过塔灵米拉贝尔和遍布庭院的魔导系统影响着这座浮空城。"
    }
  ],
  "locations": [
    {
      "name": "宁静花园区",
      "summary": "浮空城的外环区域，一个由魔法维持着生态平衡的空中花园。看似静谧优美，实则遍布着伪装成雕塑的防御魔像与经过魔法改造的致命植物，是庭院的第一道防线。",
      "layout": "位于整个浮空城的外围，包裹着中心的主宰之塔。",
      "sub_locations": [
        {
          "name": "水晶穹顶温室",
          "summary": "一个巨大的水晶温室，内部培育着早已在大陆上灭绝的魔法植物。这些植物拥有强大的自我防卫能力，会主动攻击任何非许可的进入者。"
        },
        {
          "name": "风之回廊",
          "summary": "连接花园各区域的露天回廊，常年有"鹰身"系列巡逻人偶在此飞行警戒。回廊的地面铭刻着反重力法阵，任何未授权的飞行都会受到干扰。"
        }
      ]
    },
    {
      "name": "主宰之塔",
      "summary": "艾瑞瑟尔的核心建筑，阿斯塔罗斯的法师塔。塔内完整地保存了法师纪元时期的生活设施与研究成果，由塔灵米拉贝尔直接控制，内部充满了精密的魔法陷阱与强大的战斗人偶。",
      "layout": "矗立于浮空城的正中心，是庭院的制高点。",
      "sub_locations": [
        {
          "name": "万卷图书馆",
          "summary": "占据了法师塔中三层空间的巨大图书馆，藏有海量的魔法书籍与技术文献。雷金纳德带出的蒸汽核心理论仅是这里浩瀚知识的冰山一角。书架间有负责整理的"书吏"人偶往来穿梭。"
        },
        {
          "name": "炼金工坊",
          "summary": "一个设备齐全的顶级炼金实验室，至今仍保存着许多珍稀的炼金材料和古代配方。工坊内的"助手"人偶依旧在执行着最后的生产指令，制造着未知的药剂与物品。"
        },
        {
          "name": "塔主寝宫",
          "summary": "位于塔顶的私人区域，阿斯塔罗斯曾经的居所。这里几乎未被时光侵蚀，保存着他最私人的研究笔记和一些独一无二的魔法造物。"
        }
      ]
    },
    {
      "name": "永恒之心区",
      "summary": "位于浮空城最底部的动力核心区域。一个巨大的能量水晶悬浮在此，为整个艾瑞瑟尔提供着数千年不竭的能源，其泄露的原始魔力使得此地的空间极不稳定，是整个遗迹最危险的区域。",
      "layout": "位于主宰之塔的正下方，是浮空城的基石。",
      "sub_locations": []
    }
  ]
}

