  "name": "智识之城·索菲亚",
  "parent_realm": "米拉比里斯大陆，西南海岸",
  "summary": "大陆西南海岸的独立学术城邦，一座由白色大理石与反重力水晶构筑的知识圣殿。这里是所有求知者的理想乡，在由各大学代表与法师塔主组成的议会治理下，恪守着绝对的政治中立。城中风气自由开放，充满了年轻的活力与激烈的学术辩论，空气中弥漫着旧书的墨香与炼金药剂的奇妙气味，是理性的光辉与魔法的奥秘交织之地。",
  "figures": [
    {
      "name": "伊莱诺·奥雷利安",
      "summary": "索菲亚议会的现任轮值主席，也是索菲亚综合大学的校长。一位知名的精灵历史学家，以其渊博的学识与卓越的外交手腕，在各大势力间维持着城邦的独立与中立。"
    },
    {
      "name": "大魔导师·卡利斯托",
      "summary": "阿卡纳姆法师塔的现任塔主，一位醉心于研究纯粹元素魔法的老法师。他代表着城邦的传统魔法势力，对新兴的魔导科技持保留态度。"
    },
    {
      "name": "维多利亚·阿克莱特",
      "summary": "帝国工业派大贵族，赫菲斯工学院的荣誉院长与最大赞助人。她虽不常驻于此，但其影响力确保了魔导工程学在索菲亚的地位，并为帝国输送了大量技术人才。"
    },
    {
      "name": "港务长·‘铁算盘’巴尔萨泽",
      "summary": "一位精明的矮人商人，负责管理'知识港'的一切事务。他确保了来自世界各地的物资与人员能够顺畅流入这座城市，是索菲亚与外部世界连接的关键节点。"
    }
  ],
  "locations": [
    {
      "name": "学者高地",
      "summary": "城市的学术与行政核心，坐落于地势最高的区域。宏伟的教学楼法师塔与图书馆在此汇集，构成了索菲亚最引以为傲的天际线。",
      "layout": "位于城市中心，被智慧泉大道环绕。",
      "sub_locations": [
        {
          "name": "索菲亚综合大学",
          "summary": "城邦最古老且规模最大的学府，涵盖了从历史到炼金术的几乎所有非魔法学科，其钟楼是城市的象征。"
        },
        {
          "name": "群星议会厅",
          "summary": "索菲亚最高权力机构的所在地一座没有墙壁，仅由能量力场和立柱支撑的圆形建筑，象征着知识的开放与透明。"
        },
        {
          "name": "阿卡纳姆与赫菲斯双塔",
          "summary": "分别代表传统魔法与魔导科技的两座高塔，隔着一片广场遥遥相望。阿卡纳姆法师塔古老而神秘，赫菲斯工学院则充满了金属与蒸汽的现代感，两者的并立象征着城邦内部的学术竞争。"
        },
        {
          "name": "银星之塔",
          "summary": "一座专门研究星象与预言魔法的古老法师塔，其顶部巨大的天文望远镜在夜晚会发出柔和的银光。"
        }
      ]
    },
    {
      "name": "知识港区",
      "summary": "城市的商业与对外交流门户。来自大陆各地的船只在此停靠，带来了货物财富，也带来了各种新奇的思想与异域的文化。",
      "layout": "位于城市的西部，紧邻海岸线。",
      "sub_locations": [
        {
          "name": "异客码头",
          "summary": "专门接待外国船只的码头区，这里设有各国商会的办事处，是城中最具国际化色彩的地方。"
        },
        {
          "name": "工匠与炼金行会",
          "summary": "众多手工作坊与炼金商店的聚集地学生们可以在此购买实验材料，或是委托工匠制作研究所需的精密仪器。"
        }
      ]
    },
    {
      "name": "宿舍与生活区",
      "summary": "学生与教职员工的主要居住区，充满了年轻人的活力。街道两旁遍布着咖啡馆书店小剧院与各种社团的活动室。",
      "layout": "分布在学者高地的东侧与南侧，是城市最有人气的地方。",
      "sub_locations": [
        {
          "name": "智慧泉广场",
          "summary": "生活区的中心广场，中央有一座雕刻着知识女神索菲亚的喷泉。这里是学生们集会辩论或是举办庆典的公共空间。"
        },
        {
          "name": "思辨酒馆",
          "summary": "一家以允许顾客在墙上写下学术观点和公式而闻名的酒馆。每晚都有不同学派的学生在此激烈争论，是城邦思想碰撞的前线。"
        }
      ]
    }
  ]
}

