entries.content:
{
  "name": "永雾之港·维纳利亚",
  "parent_realm": "贸易联邦，西北海岸",
  "summary": "贸易联邦的军事心脏与斯福尔扎家族的权力基石，一座终年被魔法迷雾笼罩的哥特式港都。这里是联邦唯一的军港，黑曜石般的战舰在雾中无声滑行。城市在斯福尔扎家族的铁腕下运转，其不死化的秘密警察‘无光者’是暗巷中唯一的法律。空气中弥漫着海水血腥与奢华香料混合的气息，构成了这座城市危险而又迷人的基调。",
  "figures": [
    {
      "name": "‘冷血女爵’卡特琳娜·斯福尔扎",
      "summary": "贸易联邦议会长，斯福尔扎家族的女族长。她亲自坐镇维纳利亚，以其冷酷的智慧与无情的手段，将这座城市打造成了自己最锋利的獠牙。"
    },
    {
      "name": "‘寂静之潮’洛伦佐",
      "summary": "联邦海军总司令兼‘无光者’卫队指挥官，一位沉默寡言的具有智慧的食尸鬼。他是卡特琳娜最忠诚的执行者，其麾下的舰队与秘密警察共同维系着斯福尔扎家族的统治。"
    },
    {
      "name": "‘雾中人’商会",
      "summary": "一个由海盗走私贩与情报商人组成的松散联盟，是维纳利亚地下世界的实际掌控者。他们与斯福尔扎家族维持着一种危险的平衡，处理着所有见不得光的交易。"
    },
    {
      "name": "伊索尔德女士",
      "summary": "城中最著名的销魂窟——‘血色天鹅绒’剧院的女主人。据说她与联邦所有高层都有着不清不楚的关系，剧院既是寻欢作乐的场所，也是最高级的情报交易中心。"
    }
  ],
  "locations": [
    {
      "name": "黑曜石舰队港区",
      "summary": "城市的军事核心，戒备森严的军港。巨大的海防要塞如同怪兽般盘踞在入海口，港内停泊着联邦引以为傲的蒸汽铁甲舰队。",
      "layout": "位于城市的西部，直面与阿尔比恩帝国对峙的海域。",
      "sub_locations": [
        {
          "name": "不沉船坞",
          "summary": "利用古代遗迹改造而成的巨大半潜式船坞，能够同时建造和维修多艘大型战舰。这里由不死生物工匠与人类奴工日夜劳作。"
        },
        {
          "name": "海军指挥部‘海妖之塔’",
          "summary": "一座高耸入雾的黑色玄武岩塔楼，是海军总司令洛伦佐的办公地。塔顶的魔法灯塔是唯一能穿透城市浓雾的光源。"
        },
        {
          "name": "无光者兵营",
          "summary": "秘密警察卫队的总部与训练场，一座没有窗户的堡垒式建筑。据说其地下部分比地面上更为庞大，设有审讯室与秘密监狱。"
        }
      ]
    },
    {
      "name": "永夜宫区",
      "summary": "斯福尔扎家族及附庸贵族的居住区，也是城市的政治中心。街道由苍白的魔法灯火照明，建筑风格极尽奢华与诡谲，充满了阴谋与权力的气息。",
      "layout": "位于城市的中心地带，地势较高，俯瞰着港口。",
      "sub_locations": [
        {
          "name": "泣血圣母大教堂",
          "summary": "斯福尔扎家族的私人教堂，供奉着欲望女士莉莉丝。教堂内饰极尽淫靡，是家族举行秘密仪式与血宴的场所。"
        },
        {
          "name": "斯福尔扎宫",
          "summary": "卡特琳娜的居所与联邦的现行的权力中枢。一座庞大的哥特式宫殿群，其内部如同迷宫，守护着家族数个世纪以来积累的财富与秘密。"
        }
      ]
    },
    {
      "name": "迷雾水道区",
      "summary": "城市的商业平民生活与娱乐区域。无数运河与拱桥将此地分割成蛛网般的街区，终年的雾气为这里的交易与罪恶提供了完美的掩护。",
      "layout": "位于城市的东部和南部，是城市最庞大也最混乱的区域。",
      "sub_locations": [
        {
          "name": "银匙市场",
          "summary": "城市的官方交易市场，主要进行大宗货物的贸易。但其地下的水道网络，则是‘雾中人’商会掌控的黑市所在。"
        },
        {
          "name": "血色天鹅绒剧院",
          "summary": "伊索尔德女士的产业，维纳利亚最高级的娱乐场所。这里不仅有精彩的戏剧表演，更提供各种族的美貌妓女与血奴，是权贵们夜生活的中心。"
        },
        {
          "name": "灰港",
          "summary": "平民与外来者的混居区，建筑拥挤，水道污浊。这里是城市最底层居民的挣扎之地也是各种帮派滋生的温床。"
        }

      ]
    }
  ]
}

