entries.content:
{
  "name": "亡铁之都·米兰",
  "parent_realm": "贸易联邦，东北部",
  "summary": "贸易联邦的矿业心脏与维斯孔蒂家族的龙巢，一座常年笼罩在龙脊山脉阴影下的丘陵城市。这里不见天日，空气中混杂着金属冶炼的焦糊味与死灵魔法的冰冷气息。城市的繁荣建立在无尽的矿脉与同样无尽的不死劳工之上，公开的死灵法术研究与大陆上最骇人听闻的奴隶市场是其两大名片，构成了这座城市冷酷务实且压抑的基调。",
  "figures": [
    {
      "name": "‘磐石’吉安·加莱亚佐·维斯孔蒂",
      "summary": "维斯孔蒂家族的女族长，一位讲求绝对实用主义的年长吸血鬼。她对艺术与享乐毫无兴趣，毕生致力于积累财富与巩固家族的统治，将米兰打造成了一部高效运转的死亡机器。"
    },
    {
      "name": "‘开膛手’维克托校长",
      "summary": "骸骨学院的创始者与现任校长，一位叛出帝国国教的死亡与死者之神'苍姬'的前高阶牧师。他认为死亡是生命形态的延续而非终结，致力于推广与普及标准化的死灵法术，使之成为一种高效的生产工具。"
    },
    {
      "name": "‘千貌’奴隶主",
      "summary": "万族囚笼的神秘管理者，无人知晓其真实身份种族甚至性别。此人以能搞到任何稀有货品而闻名，无论是北方的兽人酋长还是堕落的天使，只要出得起价钱，都能在TA的拍卖会上见到。"
    },
    {
      "name": "‘独眼’格里兹",
      "summary": "永暗矿坑的矿工工头，一个身经百战的矮人。他负责管理生者矿工，是矿工们与监工之间的唯一缓冲。据说他正秘密组织着一个旨在改善矿工待遇的互助会。"
    }
  ],
  "locations": [
    {
      "name": "磐影宫区",
      "summary": "城市的统治核心，维斯孔蒂家族的堡垒。建筑风格简洁坚固，充满了军事要塞的实用主义色彩，是米兰权力与秩序的源头。",
      "layout": "位于城市地势最高的丘陵之上，背靠龙脊山脉的悬崖。",
      "sub_locations": [
        {
          "name": "黑曜石王座厅",
          "summary": "维斯孔蒂家族的宫殿，是吉安族长处理政务与居住的地方。宫殿下方是家族的秘密金库与初拥转化室。"
        },
        {
          "name": "不朽者卫队兵营",
          "summary": "维斯孔蒂家族私军的驻地。这些由吸血鬼与高级不死生物混合组成的精锐部队，是维持城市高压统治的保证。"
        }
      ]
    },
    {
      "name": "骸骨学院区",
      "summary": "城市的学术与魔法中心，以高耸的死灵法师塔为标志。这里的气氛阴森但有序，充满了求知欲与对死亡本质的探讨。",
      "layout": "位于城市的东部，与矿区相邻。",
      "sub_locations": [
        {
          "name": "通识之塔",
          "summary": "骸骨学院的主体建筑，对任何支付得起高昂学费的学生开放。学院教授标准化的死灵法术，专注于如何高效转化与操控低阶不死生物用于生产活动。"
        },
        {
          "name": "尸骨陈列馆",
          "summary": "一座收藏着大陆各智慧种族完整骨骼标本的博物馆，既是教学工具，也是学院强大的潜在兵源。"
        }
      ]
    },
    {
      "name": "镣铐市场区",
      "summary": "城市的商业与罪恶中心，也是米兰最"热闹"的地方。这里不交易普通货物，唯一的商品就是各式各样的智慧生命。",
      "layout": "位于城市的西部，拥有通往城外的秘密通道。",
      "sub_locations": [
        {
          "name": "万族囚笼",
          "summary": "大陆上规模最大的奴隶市场，一个巨大的环形下沉式建筑。从普通的战俘到稀有的魔法种族，每日都有大量的奴隶在此被拍卖，满足着来自世界各地买家的欲望。"
        },
        {
          "name": "驯化场",
          "summary": "一个位于市场地下的设施，用于"处理"新到货的奴隶。反抗的意志会在这里被彻底摧垮，使其成为合格的商品。"
        }
      ]
    },
    {
      "name": "永暗矿坑区",
      "summary": "城市的经济命脉，深入龙脊山脉的巨大矿区。这里终年不见阳光，只有矿灯与魔法火焰提供照明，生者与死者在这里一同劳作，为米兰挖掘着财富。",
      "layout": "位于城市的北部，直接与龙脊山脉相连。",
      "sub_locations": [
        {
          "name": "第一矿井",
