entries.content:
{
  "name": "自由都市·威尼斯",
  "parent_realm": "贸易联邦，西南群岛",
  "summary": "贸易联邦的享乐天堂与殖民前哨，一座由比安奇家族统治的华美水都。无数洛可可风格的宫殿与桥梁构建在星罗棋布的岛屿之上，贡多拉在迷宫般的水道中穿行。这里是联邦最自由也最混乱的城市，帮派火拼是报纸的头条，‘死人乐透’是全民的消遣。作为通往远西新大陆的唯一门户，冒险的机遇与一夜暴富的梦想吸引着全大陆的投机者，构成了这座城市浮华危险而又充满无限可能的独特魅力。",
  "figures": [
    {
      "name": "‘享乐公爵’·芙拉维娅·比安奇",
      "summary": "比安奇家族的女族长，一位将自由与享乐奉为圭臬的年轻吸血鬼。她不直接干涉城市的具体事务，而是通过赞助帮派艺术家与探险家来维持一种混乱的平衡，是所有冒险者与投机者的最大保护伞。"
    },
    {
      "name": "‘船长之王’·巴托洛梅奥",
      "summary": "远西航运公会的会长，一个控制了所有前往新大陆船只的前海盗头子。任何想去新大陆淘金的人，都必须获得他的许可并支付高昂的‘保险费’。"
    },
    {
      "name": "‘九指’·罗科",
      "summary": "城中最大帮派‘泻湖之子’的首领，一个以残忍和狡猾著称的人类。他控制着赌博走私以及‘死人乐透’的盘口，是城市夜晚的无冕之王。"
    },
    {
      "name": "‘温泉乡’老板娘·咲耶",
      "summary": "远离主岛的温泉度假区‘月影岛’的女主人，一位来自翡翠迷宫的精灵。她的温泉旅馆是城中唯一绝对中立的销金窟，接待着所有需要放松与庇护的客人。"
    }
  ],
  "locations": [
    {
      "name": "黄金大运河区",
      "summary": "城市的门面与权贵中心，最宽阔的运河两岸遍布着比安奇家族及其附庸的宏伟宫殿与私人俱乐部。这里是威尼斯最奢华守备也最森严的区域。",
      "layout": "贯穿城市主岛的中央水道两岸。",
      "sub_locations": [
        {
          "name": "叹息宫",
          "summary": "芙拉维娅·比安奇的居所，一座极尽洛可可式奢华的白色大理石宫殿。这里日夜举行着盛大的宴会与假面舞会，是联邦上流社会的社交中心。"
        },
        {
          "name": "幸运女神大赌场",
          "summary": "联邦官方认证的最大赌场，也是‘九指’罗科的主要财源之一。除了常规的赌博，这里最受欢迎的项目就是对城中帮派火拼结果下注的‘死人乐透’。"
        }
      ]
    },
    {
      "name": "远航者港区",
      "summary": "城市的冒险与机遇之心，专门服务于前往远西新大陆的航线。码头上永远挤满了招募船员的船长寻找队伍的冒险者和兜售探险装备的商人。",
      "layout": "位于群岛的最西侧，面向远西新大陆的广阔海域。",
      "sub_locations": [
        {
          "name": "探险家公会",
          "summary": "冒险者协会与航运公会的联合办事处，一座由废弃海防要塞改建的建筑。墙上贴满了前往新大陆的船员招募令与高风险的探索委托。"
        },
        {
          "name": "新大陆市场",
          "summary": "一个混乱而充满活力的露天市场，专门交易从远西大陆运回的各种奇珍异宝未知矿物和被捕获的奇异生物。"
        }
      ]
    },
    {
      "name": "迷宫街市区",
      "summary": "城市的平民区与灰色地带，由无数狭窄的水道小巷和拱桥构成。这里是帮派火拼最频繁的区域，也是各种小型妓院走私窝点和秘密接头点的所在地。",
      "layout": "遍布于主岛之外的各个小型岛屿，是城市最庞大也最危险的区域。",
      "sub_locations": [
        {
          "name": "泻湖之子总部",
          "summary": "一个伪装成大型渔船仓库的建筑群，是‘九指’罗科帮派的大本营。其水下的秘密通道据说可以通往城市的任何一个角落。"
        }
      ]
    },
    {
      "name": "月影温泉岛",
      "summary": "位于主岛群东南方的独立岛屿，以其天然的魔法温泉而闻名。这里是城市唯一的净土，在老板娘咲耶的规定下，任何争斗都被严厉禁止，是所有人在血腥与阴谋后寻求片刻安宁的度假胜地。",
      "layout": "独立于主岛群之外，通过定期的渡轮与主城连接。",
      "sub_locations": []
    }
  ]
}

