entries.content:
{
  "name": "卡尔瓦德共和国",
  "parent_realm": "西方诸王国，阿尔比恩帝国以西",
  "summary": "大陆西方的革命灯塔与帝国最顽强的对手，一个在天赋人权的旗帜下诞生的共和国。它的国土遍布崎岖的山地与丘陵，无数怪物潜伏其间，锤炼了国民坚韧独立的性格。整个国家洋溢着激昂的革命热情与对自由的渴望，建筑风格从旧时代的繁复巴洛克，演变为象征着力量与理性的简约帝政风格。空气中充满了火药硝烟与山间清冽寒风混合的味道，时刻提醒着人们，自由的代价是永恒的抗争。",
  "figures": [
    {
      "name": "第一执政·玛丽安娜",
      "summary": "共和国的最高领导人，一位在内战中崛起的平民女英雄。她以坚定的意志与务实的政治手腕闻名，既是革命理想的象征，也是一个为应对内外威胁而不得不采取铁腕政策的现实主义者。"
    },
    {
      "name": "‘山地将军让路克",
      "summary": "共和国军队总司令，一位极其擅长山地游击战的军事天才。他将有限的兵力与复杂的地形完美结合，数次挫败了帝国优势兵力的入侵。"
    },
    {
      "name": "‘真理报’主编·卡米耶",
      "summary": "共和国影响力最大的报纸的主编，革命思想的坚定传播者。他的文章是无数年轻人投身革命或成为冒险者的催化剂，但其激进的言论也时常与第一执政的务实政策发生冲突。"
    },
    {
      "name": "‘怪物猎人’公会联盟",
      "summary": "由共和国境内各大冒险者公会组成的联盟，是维持国内安全清剿怪物的绝对主力。他们在民间享有崇高声望，拥有巨大的政治影响力。"
    }
  ],
  "locations": [
    {
      "name": "自由之城·瓦尔米",
      "summary": "共和国的首都，一座建立在古代陨石坑盆地中的不落要塞。城市依地势而建，层层递进，既是革命的圣地也是一座巨大的军事堡垒。建筑风格融合了旧王国的华丽与共和国的庄严，是卡尔瓦德精神的集中体现。",
      "layout": "位于国家中心地带，被险峻的环形山脉所包围。",
      "sub_locations": [
        {
          "name": "国民议会宫",
          "summary": "由旧时代的王宫改建而成，共和国的最高权力中心。宏伟的帝政风格立柱象征着共和国的权威，而宫殿前巨大的广场则是民众集会与表达意愿的场所。"
        },
        {
          "name": "革命纪念碑",
          "summary": "矗立在城市中心的一座巨大方尖碑，上面铭刻着为共和国独立与自由而牺牲的烈士姓名。碑下的长明火由魔法驱动，永不熄灭。"
        },
        {
          "name": "‘坚盾’要塞群",
          "summary": "沿着盆地边缘环形山脉修建的庞大防御工事网络。无数的炮台暗堡与魔法屏障发生器将首都武装成一个无法攻破的堡垒，是帝国军队的噩梦。"
        }

      ]
    },
    {
      "name": "铁砧镇（工业城市范例）",
      "summary": "位于龙脊山脉西麓的矿业与工业重镇，为共和国军队提供着武器与弹药。镇上遍布着大大小小的兵工厂与冶炼厂，空气中永远漂浮着煤灰与硝烟的味道。",
      "layout": "位于国家北部，靠近与帝国的边境山脉。",
      "sub_locations": []
    },
    {
      "name": "哨兵村（边境聚落范例）",
      "summary": "散布在共和国广阔边境上的无数小型武装聚落之一。每个村庄都既是农垦点，也是军事前哨，村民们平日耕作，战时则拿起武器，与游荡的怪物和偶尔入侵的帝国侦察兵搏斗。",
      "layout": "广泛分布于国内各处崎岖的山地与丘陵中。",
      "sub_locations": []
    }
  ]
}

