entries.content:
{
  "name": "圣所·天穹之眼",
  "parent_realm": "米拉比里斯，凡间上空",
  "summary": "神明在凡间的唯一前哨与快速反应部队驻地一座隐藏于云海之上，由純白金属与光路构筑的赛博朋克风格浮空城。这里是天使军团的永恒兵营，在一位轮值炽天使的绝对指挥下，以神之名监视并干预着凡间的重大危机。城市的运转高效，充满了军事化秩序，但在这永恒的宁静与戒备之下，天使们以捕捉凡人或怪物进行性爱游戏的方式，来排解无尽驻守所带来的无聊与空虚。",
  "figures": [
    {
      "name": "炽天使指挥官·萨拉菲尔",
      "summary": "由正义女神阿斯特莱雅指派的现任最高指挥官，以其严谨的战术纪律与对任务的绝对忠诚而闻名。她对城市的军事化管理一丝不苟，但对下属天使们为排解无聊而进行的"余兴活动"采取默许态度。"
    },
    {
      "name": "三位主天使副官",
      "summary": "拉结尔、哈尼尔与加百列，共同组成了天穹之眼的行政核心。她们负责所有驻守天使的人事调动后勤补给与日常戒律的维持，是确保这座巨大战争机器平稳运转的齿轮。"
    },
    {
      "name": "权天使·卡西迪",
      "summary": "‘捕猎’行动队的指挥官，负责执行捕捉高危怪物或特定凡人的任务。她热衷于寻找有趣的性爱对象，是地面世界最常能接触到的最高级天使。"
    }
  ],
  "locations": [
    {
      "name": "神谕之核区",
      "summary": "城市的最高指挥与控制中心，一座直插云霄的白色尖塔。这里是炽天使的御座所在，也是整座浮空城的中枢神经，充满了精密的光学线路与能量矩阵。",
      "layout": "位于浮空城的正中心，是城市的制高点与核心。",
      "sub_locations": [
        {
          "name": "战略全知室",
          "summary": "一个巨大的球形空间，墙壁本身就是一幅覆盖整个凡间大陆的实时全息地图。萨拉菲尔在此监视着地面的能量异常与信仰波动，下达每一个指令。"
        },
        {
          "name": "圣座终端",
          "summary": "位于全知室中央的指挥平台，是萨拉菲尔的座位，也是与神国直接通讯的唯一节点。"
        }
      ]
    },
    {
      "name": "武装天翼区",
      "summary": "天使军团的兵营与训练设施所在地由数个巨大的环形建筑构成。这里充满了肃杀之气，天使们在此进行着日复一日的战斗训练与装备维护。",
      "layout": "环绕在神谕之核的外围，是城市军事力量的集中地。",
      "sub_locations": [
        {
          "name": "模拟战场",
          "summary": "一个可以利用硬光技术模拟出任何地形与敌人的巨大训练场。天使们在此演练着对抗恶魔不死生物甚至其他天使的战术。"
        },
        {
          "name": "光铸军械库",
          "summary": "储存和维护天使制式武装的地方，从高周波震动长矛到能量护盾，所有装备都在这里由专门的天使进行维护与充能。"
        },
        {
          "name": "出击平台",
          "summary": "位于城市边缘的巨大开放式平台，是天使军团降落地面执行任务时的出发点。待命的天使小队如同雕像般在此列队，随时准备出击。"
        }
      ]
    },
    {
      "name": "宁静居所区",
      "summary": "天使们的日常生活区域，建筑风格简洁而统一，如同蜂巢般井然有序。这里没有娱乐设施，只有满足最基本生活需求的场所，气氛宁静甚至有些压抑。",
      "layout": "位于武装天翼区的外环，是城市最广阔的区域。",
      "sub_locations": [
        {
          "name": "个体休眠舱",
          "summary": "天使们休息的地方，每个天使都拥有一个独立的白色休眠舱，用于恢复能量与精神。"
        },
        {
          "name": "精液补给中心",
          "summary": "天使们补充能量的地方，如同自助餐厅。巨大的能量容器中储存着从凡间收集或人工合成的各色精液，天使们根据自己的阶级与喜好在此取用。"
        },
        {
          "name": "‘伊甸’生态园",
          "summary": "一座模拟凡间自然环境的巨大生态穹顶，也是卡西迪的‘狩猎场’。被捕捉来的凡人与怪物被放养于此，供天使们在闲暇时进入，进行狩猎与性爱的游戏，是这座城市唯一的‘乐园’。"
        }
      ]
    }
  ]
}

