entries.content:
{
  "name": "符文铁城·格林姆海姆",
  "parent_realm": "地底世界，灰矮人领地",
  "summary": "一座在地底深处由三个灰矮人氏族共同统治的符文科技之城。整座城市由巨大的钟乳石与石笋直接雕刻而成，呈现出粗犷而威严的几何美学。这里是纯粹符文技术的圣地以其出产的强大魔导装备闻名于世。城市的运转依赖于数量庞大的兽人与哥布林奴工，而灰矮人则以其极度排外与狡诈的商业信誉，维持着与地表世界危险而又利润丰厚的贸易关系。",
  "figures": [
    {
      "name": "三氏族长老议会",
      "summary": "由铁砧氏族石心氏族与黑炉氏族的三位最年长者组成的最高权力机构。他们共同决定城市的重大事务，对外保持着高度一致的排外立场，对内则维持着脆弱的力量平衡。"
    },
    {
      "name": "大工匠·布兰多·黑炉",
      "summary": "黑炉氏族的领袖，也是格林姆海姆最杰出的魔导技师。他痴迷于研发新型的魔导武器，城市的许多核心技术都出自他手，是城市技术实力的象征。"
    },
    {
      "name": "贸易执政官·索林·石心",
      "summary": "石心氏族的代表，负责与所有外来者进行交易。他以其贪婪狡诈和毫无信义而闻名，任何与他交易的地表商人都必须时刻提防被黑吃黑的风险。"
    },
    {
      "name": "‘疤面’格拉什",
      "summary": "一个被奴隶主雇佣的兽人监工，负责管理矿坑区的奴隶。他以其残暴的力量确保了生产的顺利进行，是所有奴工的噩梦。"
    }
  ],
  "locations": [
    {
      "name": "三族尖塔区",
      "summary": "城市的政治与军事核心，由三座最为巨大的石笋雕刻而成的氏族堡垒占据。这里是灰矮人的居住区，守卫森严，禁止任何外来者与奴隶进入。",
      "layout": "位于城市的最高层，俯瞰着整座城市。",
      "sub_locations": [
        {
          "name": "符文议事厅",
          "summary": "一个位于三座尖塔交汇处的巨大洞穴，是三氏族长老议会召开会议的地方。洞壁上铭刻着古老的符文，象征着三族共同的契约。"
        },
        {
          "name": "氏族堡垒",
          "summary": "铁砧石心与黑炉三个氏族各自的要塞。堡垒内部既是居住区，也设有各自的私人工坊和金库。"
        }
      ]
    },
    {
      "name": "大熔炉工坊区",
      "summary": "城市的工业心脏，魔导科技的诞生地。巨大的地热熔炉日夜不息，为城市的生产提供能源。空气中充满了魔法能量的嗡鸣与金属敲击的巨响。",
      "layout": "位于城市的中层，是城市最繁忙的区域。",
      "sub_locations": [
        {
          "name": "黑炉工坊",
          "summary": "由大工匠布兰多亲自管理的中央工坊，所有最尖端的符文装备都在这里被设计和制造出来。"
        },
        {
          "name": "魔力储能井",
          "summary": "深入地底的巨大竖井，用于收集和储存从地脉中汲取的原始魔力，是整座城市与所有符文装备的动力来源。"
        }
      ]
    },
    {
      "name": "苦工矿道区",
      "summary": "城市的经济基础，由无数兽人与哥布林奴工进行着永无休止的开采工作。这里环境恶劣，充满了压迫与绝望。",
      "layout": "位于城市的最底层，如同蛛网般向四周的岩层延伸。",
      "sub_locations": [
        {
          "name": "奴隶围栏",
          "summary": "用于关押和交易奴工的巨大洞穴，由‘疤面’格拉什这样的监工进行管理。"
        }
      ]
    },
    {
      "name": "外来者平台",
      "summary": "唯一对地表商人与冒险者开放的区域，一个悬挂在城市入口处的巨大石制平台。这里是格林姆海姆与外界连接的唯一窗口，充满了机遇也遍布着陷阱。",
      "layout": "位于城市的入口处，与城市主体严格隔离。",
      "sub_locations": [
        {
          "name": "欺诈者市场",
          "summary": "由贸易执政官索林直接控制的交易市场。地表商人在此用粮食金属和奢侈品换取灰矮人的魔导装备，但必须时刻警惕交易中的各种骗局与陷阱。"
        }
      ]
    }
  ]
}

